["sm_4_desc"] = "İŞTE YAPTIN. SOYGUNCUSUN. KULÜPTESİN. KULÜBÜN AVANTAJLARINDAN BİRİ DE BAĞLANTILAR. GAGE İLE TANIŞ. BİZE SİLAH BULACAK, GANİMETİ TAŞIMAMIZA YARDIM EDECEK. ONU DEĞERLİ BİR MÜTTEFİK SAY. LİMAN TARAFINDA BİRAZ HIRSIZLIK İŞİNİ HALLETMENİ İSTİYOR; ÇOK SESSİZ TUT.",
["sm_4_name"] = "GECE YARISI SOYGUNU",
