["sm_52_name"] = "TERSİNE DÖNÜŞ",
["sm_52_obj"] = "NO MERCY İŞİNİ ÇOK ZOR VEYA ÜZERİ ZORLUKTA TAMAMLA.$NL;BU GÖREV İÇİN LOBİDEN SOYGUNUN SONUNA KADAR OYNAMALISIN.",
