["sm_hoxton_revenge_desc"] = "HOXTON İÇERİDEKİ ZAMANINI İYİ KULLANDI. DAHA HAPİSHANE PİJAMALARINI ÇIKARMADAN FBI KARARGÂHINA GİRİP MUHBİR HAKKINDA BULABİLDİĞİ HER ŞEYİ ALDI. İSİM YOK; FEDERALLER O KADAR KURNAZ. AMA MUHBİRİN TUTULDUĞU GÜVENLİ EVİN YERİ VAR. BİTİRME ZAMANI.",
