["sm_moving_up_desc_old"] = "TAMAM, DAHA ÖNCE İNSANLARIN SENİ İZLEDİĞİNİ SÖYLEMİŞTİM. ÖZELLİKLE BİR ADAM SENİNLE İLGİLENİYOR. BU YENİ BAĞLANTIYLA BÜYÜK BİR İŞE GİRİŞEBİLİRİZ AMA AKLINDAKİ İŞ ZOR OLACAK. HAZIRLANMAN GEREKİYOR. BİRAZ DAHA HAZIR OLDUĞUNDA GERİ GEL, BEN DE GEREKENİ AYARLARIM.",
