["sokol_desc"] = "UYRUĞU: RUS$NL;YAŞI: 25$NL;$NL;GENÇ OLSA DA SOKOL EFSANEVİ BİR SOYGUNCU OLMAK İÇİN GEREKEN HER ŞEYE SAHİP. YETENEKLİ BİR ATLET OLAN SOKOL, KESKİN BİR ZEKÂYA DA SAHİP VE EKİPTEKİ ROLÜNÜ ANLIYOR. KORKUSUZ VE GÜÇLÜ; BUNU İSTER HOKEY OYUNCULARI İSTER SWAT EKİBİ OLSUN, DÜŞMANIN ARASINA DALMAK İÇİN KULLANIYOR.",
