["subtitles_0412"] = "İDEAL DEĞİL. FBI, VLAD'İN ÖZEL HAVAALANINDAKİ... SİLAH ANLAŞMASININ KOKUSUNU ALMIŞ GİBİ. BİLİYORUM. ORAYA GİDİP SANDIKLARI ONLARDAN GERİ ALMALIYIZ. GERÇEK BİR ÇATIŞMAYA HAZIRLANIN, MİLLET.",
["subtitles_0413"] = "TAMAM, HAVAALANI HEMEN YOKUŞ AŞAĞIDA. ÇİTİ KESİP GEÇİN. KASALARIN YÜKLÜ OLDUĞU KAMYONUN BULUNDUĞU HANGARI BULUN. FBI TABİİ Kİ OLAY YERİNDE. VLAD'IN SİLAHLARINI ALIP BURAYA GETİRİN.",
["subtitles_0414"] = "ÇİTTEN GİRİN, SİLAHLARI BULUP BURAYA GETİRİN. SAVAŞMAYA, HEM DE SERT SAVAŞMAYA HAZIRLANIN. BAŞLAYALIM.",
["subtitles_0415"] = "KAMYONLAR VE SİLAHLAR FBI'IN ELİNDE. KAMYONU TUTTUKLARI DEPOYU BULUN. FBI'A AĞIR BİR DARBE İNDİRİP SİLAHLARLA BURAYA DÖNÜN. BOL ŞANS, BU KARMAŞA İÇİN KUSURA BAKMAYIN.",
["subtitles_0416"] = "TAMAM, GİTMEYE HAZIRIZ. SİZİ GÜVENLİ EVE KADAR SAĞ SALİM GÖTÜRECEĞİM. VLAD'I MEMNUN EDECEK SİLAHLAR BİZDE. EMİNİM ÇOK HOŞUNA GİDECEK. FBI İSE... BAŞKA MESELE.",
["subtitles_0417"] = "İYİ UYGULANDI. SİLAHLAR GÜVENE ALINDI, VLAD DA PARAMIZI HAZIRLIYOR. HADİ TAHSİL EDELİM.",
["subtitles_0418"] = "KIL PAYIYDI. SİLAHLARI YOKUŞTAN YUKARI TAŞIRKEN İYİ İŞ ÇIKARDINIZ. ARTIK VLAD ORDUSUNU KURACAK, BİZ DE GERÇEKTEN GÜZEL PARA KAZANACAĞIZ.",
["subtitles_0419"] = "BENİ HİÇ HAYAL KIRIKLIĞINA UĞRATMIYORSUNUZ. TAM TAKIM BEYLER. VLAD BU İŞLE GURUR DUYACAK. ARTIK GERÇEKTEN İŞ YAPIYORUZ.",
["subtitles_0428"] = "GANİMET ÇANTALARINIZI KULLANIP AĞZINA KADAR DOLDURUN. DC'DEYİZ, SİLAHLAR PATLAYARAK GİRERSENİZ POLİSLERİN ÇOK ÇABUK GELMESİNİ BEKLEYİN.",
["subtitles_0430"] = "AMA BURASI HÂLÂ DC, BALTİMORE DEĞİL... SİLAHLARI KONUŞTURARAK GİRERSENİZ BASKI BEKLEYİN.",
["subtitles_0470"] = "HADİ YAPALIM ŞU İŞİ.",
["subtitles_0474"] = "NASIL BİR GANİMETTEN SÖZ ETTİĞİMİZİ BİLMİYORUM, HER ŞEYE HAZIR OLUN. KAÇARKEN MİNİBÜSÜ KULLANIN.",
["subtitles_0475"] = "MEĞER BURANIN BANKA MÜDÜRÜ ÇENESİNİ KAPALI TUTMALIYMIŞ. BİZİM ADAMLARDAN BİRİ, GÜVENLİKLERİNİN NE KADAR HARİKA OLDUĞU, SİCİLLERİNDE LEKE BULUNMADIĞI FALAN DİYE BÖBÜRLENDİĞİNİ DUYMUŞ. ",
["subtitles_0476"] = "ZORLU BİR İŞİ KİM SEVMEZ, DEĞİL Mİ?",
["subtitles_0477"] = "BURADA HER ŞEY OLABİLİR. DEVLET SIRLARI, KİRLİ ÇAMAŞIRLAR, HOPE DİAMOND... HİÇ BELLİ OLMAZ. ŞU BANKAYI VURALIM DA ÖĞRENELİM, NE DERSİNİZ?",
["subtitles_0478"] = "MEĞER BUGÜN ŞEHİR DIŞINDAKİ KUMARHANELERE ZIRHLI KAMYONLA GÖNDERMEK İÇİN NAKİT YIĞDIKLARI GÜNMÜŞ. ZARLARI ATALIM. ",
["subtitles_0480"] = "İÇERİ GİRİP BULDUĞUMUZ BÜTÜN KÜÇÜK KARE PAKETLERİ ALALIM. EMİNİM ÇOK PARA EDER.",
["subtitles_0486"] = "HER YER KİRALIK KASAYLA DOLU. İÇİNDE NE VAR KİM BİLİR, TESTERE GETİRİP KESMEYE BAŞLAYIN.",
["subtitles_0487"] = "BİR SÜRÜ KİRALIK KASA TUTMUŞ BİR \"İŞ ADAMINDAN\" HABER ALDIM... KAÇIRILMAYACAK KADAR TATLI FIRSAT, DEĞİL Mİ? YAPALIM.",
["subtitles_0488"] = "KİRALIK KASALARDAN BAŞLAYIP BANKAYI BOŞALTALIM... EMİNİM İÇLERİ TÜRLÜ SIRLA DOLUDUR...",
["subtitles_0489"] = "BANKA KARŞINIZDA. İÇERİ GİRİN, GANİMETİ ALIN VE SOĞUKKANLI KALIN.",
["subtitles_0490"] = "SOYGUN VAKTİ. SİVİLLERİ KONTROL ALTINDA TUTUN, TELEFON KULLANMASINLAR, KAMERALARA DİKKAT EDİN. MİNİBÜSTE GÖRÜŞÜRÜZ.",
["subtitles_0492"] = "TAMAM MİLLET. HERKES HAZIR MI? BURAYI BOŞALTALIM. ",
["subtitles_0493"] = "BİLİYORUM, BUNU EZBERE BİLİYORSUNUZ. SİVİLLERİ YÜZÜSTÜ YATIRIN, TERMAL MIZRAĞI DA YAKIN. HADİ.",
