["time_escape"] = "KAÇIŞA KALAN SÜRE",
["time_trial"] = "DENEME SAYACI",
["tip_ammo_bag"] = "MÜHİMMATIN SIK SIK BİTİYORSA BİR MÜHİMMAT ÇANTASI GETİRMEN İYİ OLABİLİR. $NL; $NL; MÜHİMMATIN AZALDIĞINDA MÜHİMMAT ÇANTASINI YERE KOY VE CEPHANENİ YENİLEMEK İÇİN KULLAN.",
["tip_doctor_bag"] = "DOKTOR ÇANTASI TAM BİR HAYAT KURTARICIDIR. $NL; $NL; EKİBİNİN SAĞLIĞI AZALIRSA DOKTOR ÇANTANI YERE KOY VE HERKESİN KENDİNİ TEDAVİ ETMESİNİ SAĞLA!",
["tip_dont_shoot_civilians"] = "SİVİLLERE ATEŞ ETME. ÖLDÜRDÜĞÜN HER SİVİL İÇİN NORMAL GÖZALTI SÜRENE CEZA SÜRESİ EKLENİR. $NL; $NL; YANİ GÖZALTINA ALINIRSAN POLİSİN SENİ BİR REHİNEYLE TAKAS ETMEYİ TEKLİF ETMESİ İÇİN DAHA UZUN SÜRE BEKLEMEN GEREKİR.",
["tip_head_shot"] = "KAFAYA İSABET EDEN ATIŞLAR, VÜCUDUN DİĞER BÖLGELERİNE İSABET EDENLERDEN DAHA ETKİLİDİR.",
["tip_help_arrested"] = "MEYDAN OKUMALARI TAMAMLAMAYA ÇALIŞ; PARA KAZANDIRIRLAR VE HIZLI İLERLEMEK İÇİN İYİ BİR YÖNTEMDİR. $NL; $NL; TÜM MEYDAN OKUMALAR VE HEDEFLERİ ANA MENÜDE LİSTELENİR.",
["tip_help_bleed_out"] = "VURULUP YERE DÜŞEN SOYGUNCU \"KAN KAYBI\" DURUMUNA GİRER; HAREKET EDEMEZ VE YALNIZCA BEYLİK SİLAHIYLA ATEŞ EDEBİLİR. $NL; $NL; KAN KAYBI DURUMUNDAKİ BİR SOYGUNCU, HİÇBİR BEDEL ÖDEMEDEN YARDIMLA KALDIRILABİLİR.",
["tip_law_enforcers_as_hostages"] = "REHİN ALABİLECEĞİN SİVİL YOKSA KOLLUK KUVVETLERİNİ REHİN ALABİLİRSİN.",
["tip_mask_off"] = "MASKENİ TAKMADIYSAN KOLLUK KUVVETLERİNİN DİKKATİNİ ÇEKMEZSİN; BUNU AVANTAJINA KULLAN. $NL; $NL; MASKELERİNİZİ TAKMADAN ÖNCE MEKÂNI KEŞFEDİN VE YERLERİNİZİ ALIN. MASKENİ BİR KEZ TAKTIĞINDA SOYGUN BİTENE KADAR ÇIKARAMAZSIN.",
["tip_melee_attack"] = "SİLAHININ DİPÇİĞİYLE VURMAK, BİR RAKİBİN İŞİNİ BİTİRMEK İÇİN İYİ BİR YÖNTEM OLABİLİR. $NL; $NL; ÖZELLİKLE MÜHİMMATIN AZALDIĞINDA İŞE YARAR.",
["tip_objectives"] = "MEVCUT HEDEFİN EKRANIN SOL ÜST KÖŞESİNDE GÖSTERİLİR. $NL; $NL; HEDEFİN DAHA AYRINTILI AÇIKLAMASINI VE TAMAMLANAN HEDEFLERİN LİSTESİNİ BİLGİ EKRANINDA GÖREBİLİRSİN.",
["tip_police_free_hostage"] = "YAKINDA BİR SOYGUNCU YOKSA POLİS, REHİNELERİ KURTARMAK İÇİN HER FIRSATI DEĞERLENDİRİR. $NL; $NL; EKİBİNİZİ DAĞITIP TÜM REHİNELERİ GÖZLEYİN; ONLAR SİZİN HAYAT SİGORTANIZ!",
["tip_secret_assignmnet"] = "DÖRT ÖZEL BİRİM TÜRÜ DE ÇOK TEHLİKELİDİR; ÖZELLİKLE DE TEK BAŞINAYSAN. $NL; $NL; ONLARI İNDİRMEK İÇİN BİRLİKTE HAREKET EDİN!",
["tip_select_reward"] = "BİLGİ EKRANINDA, FARKLI ALANLARDA UZMANLAŞMANI SAĞLAYAN ÇEŞİTLİ BECERİ AĞAÇLARI ARASINDAN SEÇİM YAPABİLİRSİN. $NL; $NL; BU AĞAÇLAR FARKLI AVANTAJLAR VE SİLAHLAR VERİR; İTİBARIN YETERİNCE YÜKSEKSE HEPSİNE SAHİP OLABİLİRSİN.",
["tip_shoot_at_civilians"] = "SİVİLLERİ KONTROL ALTINDA TUTMAK İÇİN ONLARA BAĞIR. $NL; $NL; HAYATTAKİ BİR SİVİL HER ZAMAN İŞİNE YARAR; YERE YATTIĞINDA HAYATTA KALMA OLASILIĞI ARTAR.",
["tip_shoot_in_bleed_out"] = "KAN KAYBI DURUMUNDAYKEN BEYLİK SİLAHINI KULLANABİLİRSİN. $NL; $NL; BİR ARKADAŞIN SENİ KALDIRIRKEN İKİNİZİ DE KORUYABİLİRSİN; ANCAK YALNIZKEN KOLLUK KUVVETLERİNİ KIŞKIRTIRSAN KOLAY VE SAVUNMASIZ BİR HEDEF OLURSUN.",
["tip_steelsight"] = "NİŞAN ALARAK ATEŞ ETMEK, BEL HİZASINDAN ATEŞ ETMEKTEN DAHA İSABETLİDİR.",
["tip_switch_to_sidearm"] = "BEYLİK SİLAHINA GEÇMEK, BİRİNCİL SİLAHINI DOLDURMAKTAN HER ZAMAN DAHA HIZLIDIR. $NL; $NL; BU YÜZDEN ZOR DURUMDAYKEN HAFİF MAKİNELİ SİLAHININ MÜHİMMATI BİTERSE DOLDURMAK YERİNE BEYLİK SİLAHINA GEÇMEK HAYATINI KURTARABİLİR.",
["tip_tactical_reload"] = "ŞARJÖRÜNÜ TAMAMEN BOŞALTMADAN DA SİLAHINI DOLDURABİLİRSİN. $NL; $NL;BÖYLECE BİR SONRAKİ ÇATIŞMAYA DOLU ŞARJÖRLE GİRERSİN. BUNA \"TAKTİK DOLDURMA\" DENİR.",
["tip_tips"] = "İPUÇLARI:",
["tip_trading_hostage"] = "TÜM SAĞLIĞINI KAYBEDEN SOYGUNCU GÖZALTINA ALINIR. GÖZALTINDAYKEN YALNIZCA REHİNE TAKASIYLA GERİ DÖNEBİLİRSİN. $NL; $NL; POLİS, TAKASI AYARLAMAK İÇİN BAIN'LE İLETİŞİME GEÇER.",
["tip_weapon_effecienty"] = "FARKLI SİLAHLAR FARKLI MESAFELERDE DAHA ETKİLİDİR; BU YÜZDEN FARKLI DURUMLARA UYGUNDURLAR.",
["tip_xp"] = "HEDEFLERİ VE MEYDAN OKUMALARI TAMAMLAYARAK, AYRICA GANİMET ÇALARAK PARA KAZANIRSIN. $NL; $NL; PARA ÖDÜLLERİ TOPLAMAK İTİBARINI ARTIRIR; BU DA YENİ SİLAHLARA, EKİPMANLARA VE YETENEKLERE ERİŞMENİ SAĞLAR.",
["tip_xp_bar"] = "PARA GÖSTERGESİ EKRANIN SOL ALT KÖŞESİNDEDİR. $NL; $NL; BİR SONRAKİ İTİBAR SEVİYESİNE ULAŞMAK İÇİN DAHA NE KADAR PARA TOPLAMAN GEREKTİĞİNİ VE HANGİ SİLAHI, EKİPMANI VEYA YETENEĞİ ÖDÜL OLARAK ALACAĞINI GÖSTERİR.",
["toolset"] = "BU YÜKSELTME, ETKİLEŞİMLERİ HIZLANDIRIR.$NL; BİR YERE ÇOK HIZLI GİRİP ÇIKMAN GEREKİYORSA ALET ÇANTASI İŞİNE YARAYABİLİR.",
["tpm_pal_01_01"] = "ŞEY, PARDON, YANLIŞ NUMARA...",
["tpm_pal_01_02"] = "AH, KUSURA BAKMA DOSTUM, YANLIŞ NUMARAYI ARAMIŞIM.",
["tpm_pal_01_03"] = "EE, NE? YANLIŞ NUMARAYI ARAMIŞ OLMALIYIM, KUSURA BAKMAYIN.",
