["trai_intro_01_01"] = "DOĞRU MU ANLADIM? DALLAS'TAN OLMAYAN DALLAS ADLI BİR ADAMINIZ, HOUSTON'A HİÇ GİTMEMİŞ HOUSTON ADLI BİR ADAMINIZ VAR?",
["trai_intro_01_02"] = "ÇOK TUHAF, DEĞİL Mİ? SANIRIM O KADAR YER VARKEN CHİCAGO'DAN GELMİŞLER.",
["trai_intro_01_03"] = "HAH. İŞLERİNİ YAPSINLAR DA KENDİLERİNE NE BOK DİYORLARSA DESİNLER. BEN BÖYLE DÜŞÜNÜYORUM.",
["trai_intro_02_01"] = "BU BASKI KALIPLARINI NASIL ÖĞRENDİNİZ? ORDU İŞİN İÇİNDEYSE O BİLGİYİ ALMAK KOLAY OLAMAZ.",
["trai_intro_02_02"] = "BENİM BURALARDAN NELER GEÇİP GİDİYOR, BİLMEK İSTERİM. TEXAS'IN HER YERİNDE GÖZÜM VAR. KAÇAKÇILIK ŞEBEKEMİN DE ÇOK YÜKSEK YERLERDE ORTAKLARI VAR.",
["trai_intro_02_03"] = "BURADA İŞLER YOLUNDA GİDERSE O ORTAKLARLA BİR ARA TANIŞMAYI İSTERİZ. KENDİMİZİ İŞE YARAR KILMANIN YOLLARINI HEP ARARIZ. DOĞRU FİYATA.",
["trai_intro_03_01"] = "ORDUYA KARŞI ÇIKMAKTAN GERGİN GÖRÜNMÜYORSUNUZ. HİÇ.",
["trai_intro_03_02"] = "BUGÜNE KADAR BİR SÜRÜ BELALIYLA KAPIŞTIK. MURKYWATER. THE GOLDEN DAGGER TRIAD. FBI'I BİLE SOYDUK. ",
["trai_intro_03_03"] = "VAY AMINA KOYAYIM! BÜYÜK LİGDESİNİZ! SIRADA NE VAR? FORT KNOX? HA, LANET BEYAZ SARAY MI? HAYAL EDEBİLİYOR MUSUNUZ?",
["trai_intro_03_04"] = "HAHAHA... EVET...",
