["vit_intro_01_01"] = "İŞTE BU MİLLET, İŞTE BU. HEY LOCKE, ALTINI UNUTMADIN, DEĞİL Mİ?",
["vit_intro_01_02"] = "LOCKE HİÇBİR ŞEYİ UNUTMAZ!",
["vit_intro_01_03"] = "ÖZELLİKLE O BEREYİ...",
["vit_intro_01_04"] = "OLYMPUS BİRAZDAN SİKTİR OLUP GİDECEK.",
["vit_intro_01_05"] = "BİLİYOR MUSUNUZ, GALİBA YAPTIĞIMIZ ŞEYİN CİDDİYETİNİ DAHA YENİ ANLADIM.",
["vit_intro_01_06"] = "DAHA BÜYÜK SİLAHLAR GETİRMELİYDİK ÇOCUKLAR.",
["vit_intro_01_07"] = "HEY, SAKİNLEŞ DE BİR MUZ YE.",
["vit_intro_01_08"] = "ELİMİZDEKİ YETERİNCE BÜYÜK.",
["vit_intro_01_09"] = "HAY SİKEYİM...",
["vit_intro_01_10"] = "BU İŞ RESMEN 'ULUSLARARASI KRİZ' DİYE BAĞIRIYOR.",
["vit_intro_01_11"] = "AH, SİKTİR EDİN. BU BOKU YAPIYORUZ.",
["vit_intro_01_12"] = "HERKES HAZIR MI?",
["vit_intro_02_01"] = "UNUTMAYIN MİLLET, BU HER ŞEY İÇİN. TENEKE KUTU DA DÂHİL.",
["vit_intro_02_02"] = "BAIN, HASTA OLDUĞUNU BİLİYORUM AMA KESİNLİKLE EN KÖTÜ ŞAKAYDI!",
["vit_intro_02_03"] = "AH, BUNDAN KURTULMAMIZIN İMKÂNI YOK ÇOCUKLAR.",
["vit_intro_02_04"] = "KAÇMAK İSTEDİĞİNİZ OLDUYSA... EH, ARTIK ÇOK GEÇ.",
["vit_intro_02_05"] = "BU İŞTEN KAÇMAK YOK. BAIN'İN BAŞLATTIĞINI BİTİRECEĞİZ.",
["vit_intro_02_06"] = "HEM DE NASIL. LANET DENTİST ORTAYA ÇIKARSA ONU DA BİTİRECEĞİZ.",
["vit_intro_02_07"] = "EN İYİ YANI, GERÇEKTEN BAŞARABİLİRSEK İSTEDİĞİMİZ KADAR KONUŞABİLİRİZ!",
["vit_intro_02_08"] = "BİR GÜN BUNUN FİLMİNİ YAZACAĞIM. BELKİ DİZİ OLUR.",
["vit_intro_02_09"] = "ŞU VİDEO OYUNU DENENLERDEN NİYE OLMASIN?",
["vit_intro_02_10"] = "GERÇEKTEN YAPIYOR MUYUZ? GERÇEKTEN YAPIYORUZ!",
["vit_intro_03_01"] = "HAZIR MISINIZ MİLLET? BÜTÜN ZAMANLARIN EN BÜYÜK SOYGUNU!",
["vit_intro_03_02"] = "LOCKE, BU LANET HELİKOPTERİ DÜŞÜRMEYECEĞİNE SÖZ VERİRSEN SANA YENİ BİR GOLF SOPASI TAKIMI ALIRIM, TAMAM MI?",
["vit_intro_03_03"] = "SÖZÜNÜ TUTTURACAĞIM SANA, GERZEK!",
["vit_intro_03_04"] = "SAKİN OL HOX, ESKİ SAVAŞ FİLMLERİNDEN BİRİ GİBİ.",
["vit_intro_03_05"] = "SAVAŞ FİLMLERİNDEN NEFRET EDERİM AMINA KOYAYIM.",
["vit_intro_03_06"] = "DEMEK BÜYÜK İŞ GELDİ ÇATTI.",
["vit_intro_03_07"] = "HEY DUKE, BİR YIL ÖNCE BUNU YAPACAĞINI DÜŞÜNÜYOR MUYDUN?",
["vit_intro_03_08"] = "DUYDUĞUNUZ, SİZE ANLATILAN ONCA KOMPLO TEORİSİ VAR AMA BUNA KİM İNANIRDI Kİ?",
["vit_intro_03_09"] = "İNAN DOSTUM. İNAN BE.",
["vit_intro_03_10"] = "'BİR KEZ DAHA GEDİĞE HÜCUM...'",
["vit_intro_03_11"] = "ŞİMDİ DE SİKTİĞİMİN MİLTON'I MI OLDUN?",
["vit_intro_03_12"] = "SHAKESPEARE HOX. SHAKESPEARE.",
["vit_intro_03_13"] = "VAKTİMİZ OLURSA İÇERİDEKİ SANAT ESERLERİNDEN BAZILARINI... TAKDİR EDECEĞİM!",
["vit_intro_03_14"] = "BUYUR!",
["vit_intro_04_01"] = "LİNCOLN YATAK ODASINDA BİR GECE KALMAYA NE DERSİNİZ?",
["vit_intro_04_02"] = "LANET OLSUN LOCKE, BUNUN İÇİN SENİ PATAKLAYACAĞIM.",
["vit_intro_04_03"] = "BENİ NİYE SUÇLUYORSUN? BENİM FİKRİM DEĞİLDİ!",
["vit_intro_04_04"] = "İŞLER SARPA SARARSA YEDEK PLANIMIZ VAR MI?",
["vit_intro_04_05"] = "DEDİĞİM ŞU: BURADAN ÇOK ÇABUK DEFOLUP GİDECEĞİZ.",
["vit_intro_04_06"] = "MERAK ETME.",
["vit_intro_04_07"] = "NEDEN DÜNYANIN SONU GELMİŞ GİBİ HİSSEDİYORUM LAN?",
["vit_intro_04_08"] = "ÇÜNKÜ BELKİ GERÇEKTEN ÖYLEDİR AMINA KOYAYIM.",
["vit_intro_04_09"] = "PLANIMIZ SAĞLAM. HİÇBİR ŞEY TERS GİTMEYECEK.",
["vit_intro_04_10"] = "BU İŞ BİTİNCE BAIN'İN BAHSETTİĞİ ŞU PLAJI SATIN ALALIM MI AMINA KOYAYIM?",
["vit_intro_04_11"] = "BENCE DE İYİ.",
["vit_intro_04_12"] = "ASLINDA AKLIMDA BAŞKA BİR ŞEY VAR. DALLAS BUNDAN NEFRET EDECEK...",
["vit_intro_05_01"] = "VAY. YAKINDAN GERÇEKTEN KÜÇÜKMÜŞ.",
["vit_intro_05_02"] = "BU KADAR İLERLEYECEĞİMİZİ HİÇ DÜŞÜNÜR MÜYDÜNÜZ, SİZİ OTUZBİRCİLER?",
["vit_intro_05_03"] = "MURKY'LER HAKKINDAKİ İSTİHBARATIMIZIN KÖTÜ OLMASINDAN BİRAZ ENDİŞELİYİM.",
["vit_intro_05_04"] = "DÜŞÜNME. DİĞER İŞLER GİBİ ELE AL.",
["vit_intro_05_05"] = "TAVŞAN DELİĞİNİN SONU.",
["vit_intro_05_06"] = "HADİ, NEŞELEN. DAHA BİTMEDİ, DEĞİL Mİ?",
["vit_intro_05_07"] = "İŞTE BU BE. DAHA BİTİRMEDİK.",
["vit_intro_05_08"] = "MEKÂNI BİZE ARDINA KADAR AÇIK BIRAKMALARI NE HOŞ.",
["vit_intro_05_09"] = "HEY DUKE, ŞU ARK OF THE WATCHER MESELESİ DE NE?",
["vit_intro_05_10"] = "AŞAĞIDA GÖMÜLÜ UZAY GEMİSİ OLMASINI HÂLÂ UMUYORUM.",
["vit_intro_05_11"] = "NE, YAKIN TEMAS MI ARIYORSUN AMINA KOYAYIM?",
["vit_intro_05_12"] = "ASIL SORU BU, DEĞİL Mİ?",
["vit_intro_05_13"] = "TAMAM MİLLET. ROLE GİRME VAKTİ.",
["vld_airport_brf_outro_01"] = "SAVAŞ SÜRMELİ, KALASHNİKOV'LAR BENİM OLMALI! GİDİN! GİDİP SORUNU DÜZELTİN!",
["vld_airport_brf_speak_01"] = "ÖZEL HAVAALANINDA ADAMLARIMI FBI TUTUKLADI. MEMLEKETTEN SİLAHLAR VARDI YANLARINDA, KALASHNİKOV FALAN. PARAM GİTTİ AMA SİLAHLAR HÂLÂ ORADA.",
["vld_airport_brf_speak_01b"] = "İÇERİ GİRMENİZİ, DEPODAN ÇIKMADAN ÖNCE (SİKTİĞİMİN POLİSİNDEN) GERİ ALMANIZI İSTİYORUM. ŞİMDİ ÇOK ACELE EDİYORSUNUZ, ANLIYORSANIZ.",
["vld_airport_brf_speak_02"] = "SİLAHLARIM FBI'DA. İYİ TEDARİKÇİM PARAYI ALIP GİTTİ AMA BANA ŞİMDİ SİLAH LAZIM. ÖZEL HAVAALANINDAKİ DEPODA, BİR KAMYONDA OLACAKLAR. HIZLI GİDİN ÇÜNKÜ FBI BÖLGEYİ KAPATIYOR.",
["vld_airport_brf_speak_03"] = "BU SAVAŞIN SÜRMESİ İÇİN SİLAH LAZIM. ŞİMDİ BENİM OLAN FBI'DA. PARA GİTTİ AMA TEÇHİZAT HÂLÂ HAVAALANINDA. GİDİP ŞU LANET SİLAH SANDIKLARINI GERİ ALIN.",
["vld_airport_brf_speak_03b"] = "EN KALİTELİ RUS KALASHNİKOV'LARINI BEKLEYİN, ÇOK İYİ! ÇOK GÜZEL.",
["vld_airport_cnc_01"] = "ACİL İHTİYACIM VAR. İŞİM KESİLDİ, POLİS MALLARIMIN BAŞINDA.",
["vld_airport_cnc_02"] = "HAVAALANINDAKİ SİLAH ANLAŞMAM İSPİYONLANDI. RAKİPLER, EMİNİM. YARDIM EDİP SİLAHLARI GERİ ALMALISINIZ.",
["vld_airport_cnc_03"] = "AK'LERİM ARTIK FBI'IN ELİNDE. BUNU SEVMİYORUM. ORADA ÇOK PİS POLİS VAR. SİLAHLARIMI GERİ İSTİYORUM. BURADA SİZİN İÇİN FIRSAT VAR BENCE.",
["vld_airport_debrief_01"] = "KALASHNİKOV'LAR ADAMLARIMLA GERİ DÖNÜYOR. (TEŞEKKÜRLER) BUNU YAPANLARI YOK EDECEĞİM.",
["vld_airport_debrief_02"] = "FBI KAYBETTİ, BİZ KAZANDIK. KAZANMAYI SEVERİM. KALASHNİKOV'LAR ARTIK VLAD'IN ORDUSUNDA. VLAD'IN PARASIYLA KUTLAYIN DOSTLAR.",
["vld_airport_debrief_03"] = "ZOR BİR ALIŞVERİŞTİ. AMA TEDARİKÇİM İYİ... KALASHNİKOV'LAR DA İYİ. HER ŞEY İYİ. (TEŞEKKÜRLER)",
["vld_airport_debrief_04"] = "ARTIK HİÇBİR ŞEY VLAD'I DURDURAMAZ, HİÇBİR ŞEY! BU ŞEHRİN KRALI OLACAĞIM. ADAMLARIM DA İYİ KAZANÇ İÇİN KULLANACAĞIM ORDUM OLACAK. BELKİ BİZİ HABERLERDE GÖRÜRSÜNÜZ. SİZ GÜLÜMSERSİNİZ, BEN DE, BEN DE GÜLÜMSERİM...",
["vld_as1_01_01"] = "BU AÇIK MI? ALO... NEREDE O LANET PALYA... AH, İŞTE BURADASINIZ!",
["vld_as1_01_02"] = "DENEME, DENEME... BİR, İKİ... MARY KÜÇÜK BİR KUZUYU SİKTİ. AA, ORADASINIZ!",
["vld_as1_01_03"] = "SİKTİĞİMİN TELEFONLARI SİKİLMİŞ. AH, DOSTLARIM!",
["vld_as1_02_01"] = "BU İŞ ÖNEMLİ. KAMYONLARDAKİ KASALARI ÇIKARMANIZ GEREK... ŞEY, SAĞ SALİM. DUYDUNUZ MU?",
["vld_as1_02_02"] = "İYİ DİNLEYİN. O KASALARIN HER BİRİNİ GERİ ALMANIZ GEREKİYOR. BENİ HAYAL KIRIKLIĞINA UĞRATAMAZSINIZ.",
["vld_as1_02_03"] = "KULAK AÇIN. KASALAR KAMYONLARDA. İSTİSNASIZ HEPSİNİ ÇIKARMANIZ GEREK. SAĞ SALİM. ŞİMDİ KULAK KAPATIN. KASALARI ALIN.",
["vld_as1_03_01"] = "HADİ PALYAÇOLAR! KAMYONLARI BULUN! BÜYÜK, YEŞİL, TEKERLEKLERİ VAR... İŞTE ÖYLE!",
["vld_as1_03_02"] = "MANZARA SEYRETMEYİ BIRAKIN DA O KAMYONLARI BULUN!",
["vld_as1_03_03"] = "HEY, GÜNEŞ Mİ ALIYORSUNUZ LAN GÖTLER? KAMYONLAR VARDI, HATIRLADINIZ MI?!",
["vld_as1_04_01"] = "ŞU KAMYONLARI AÇIN! PARMAKLARINIZI GÖTÜNÜZDEN ÇIKARIN!",
["vld_as1_04_02"] = "O KAMYONLARI KESİP AÇIN DOSTLARIM.",
["vld_as1_04_03"] = "HADİ PALYAÇOLAR, KAMYONLARI AÇIN!",
["vld_as1_05_01"] = "EVET! GÜZEL, KASALAR ORADA. BEBEKLERİM. 400 LİBRE AĞIRLIĞINDAKİ BEBEKLERİM. SIRTINIZDA TAŞIMAYA KALKARSANIZ BELİNİZİ KIRARLAR. BİR NAKLİYE ARACI ARAYIN.",
["vld_as1_05_02"] = "KASALAR ORADA. NE GÜZELLER. GÜVENLE ÇIKARMAK İÇİN ARAÇ GEREKECEK. ETRAFA BAKIN.",
["vld_as1_05_03"] = "AHHH, KASALAR. BENİM KÜÇÜK KIYMETLİLERİM. ONLARI GÜVENLE DIŞARI ÇIKARIN. BİR TAŞIMA ARACI BULUN.",
["vld_as1_08_01"] = "AHHH! LA! YÜZME HAVUZLARI, FİLM YILDIZLARI... KOKAİN ALIŞKANLIKLARI, YIKILMIŞ HAYALLER. BAYILIYORUM.",
["vld_as1_08_02"] = "BÜYÜK DEPREM BUYDU DİYORLAR. 8,8 BÜYÜKLÜĞÜNDE. BİLİM İNSANI DEĞİLİM AMA SANIRIM LA SIÇTI DEMEK BU. HAHA!",
["vld_as1_08_03"] = "CALİFORNİA PASİFİK'E BATIYOR. O KASALAR DA YÜZMÜYOR.",
["vld_as1_08_04"] = "BU KALİFORNİYALILAR ÇOK KABA. BİRAZ DC TERBİYESİ ÖĞRETİN.",
["vld_as1_08_05"] = "HAFTALARCA MOLOZLARDAN POLİS PARÇALARI ÇIKARACAKLAR!",
["vld_as1_08_06"] = "EN SAĞLAM SIRT KİMDE? HADİ, VLAD AMCANIZA NASIL TAŞIDIĞINIZI GÖSTERİN!",
["vld_as1_08_07"] = "O KASALARI BURADAN ÇIKARMANIZI İSTİYORUM. YA ARTÇI DEPREM OLURSA?",
["vld_as1_08_08"] = "BATI YAKASI KASALARINI DOĞU YAKASI OYUNCULARIMA GETİRİYORUM!",
["vld_as1_08_09"] = "LA'İN YENİ SÜPER YILDIZLARI SİZ OLACAKSINIZ. YAKIŞIKLI, TEHLİKELİ... DUBLÖRLÜKLERİNİ BİLE KENDİLERİ YAPIYOR!",
["vld_as1_08_10"] = "SİZ KENDİ ÇİZGİLERİNİZİ BİLİRSİNİZ. BENİM BİLDİĞİM ÇİZGİLER DE BELLİ. EVET, SİKTİĞİMİN SPUTNİK'İ! HAHA!",
["vld_as1_08_11"] = "BELALI EKİP TARAFINDAN EN İYİ PERFORMANS OSCAR'INA ADAYSINIZ.",
["vld_as1_08_12"] = "ŞU DARMADAĞIN BETONA BAKIN. YANGINLAR. ÇIĞLIKLAR. BURAYI DAHA DA SEVDİM! HAHA!",
["vld_as1_08_13"] = "BU DEPREM KİM BİLİR KAÇ KİRLİ SIRRI GÜN YÜZÜNE ÇIKARACAK.",
["vld_as1_08_14"] = "BU BATI YAKASI EKİBİ KASALARDA SAKLANAN, ÇOK SAYIDA ÖZELLEŞTİRME ÜRÜNÜ TAŞIMAKTA UZMAN. BENİ DOĞU YAKASI'NDAKİ ADAMLARI YAPTILAR. BÜYÜK İŞ! GİRİŞ BİLETİM!",
["vld_as1_09_01"] = "PATLAYICILARDAN ÇEKİNMEYİN DOSTLAR. C4 İYİDİR. C4 DOSTTUR, DEĞİL Mİ?",
["vld_as1_09_02"] = "C4'Ü NEDEN KİMSE ALMIYOR? VLAD BUNU ANLAMIYOR.",
["vld_as1_09_03"] = "C4'TEN KORKMAYIN. PATLAMAZ. EN AZINDAN HENÜZ. VLAD KOMİKTİR...",
["vld_as1_10_01"] = "ŞU C4 MÜ? ZAVALLI KAYIP BEBEKMİŞ GİBİ DAVRANIN. SEVİN, BÜYÜTÜN... SONRA DUVARA KOYUP PATLATIN! EVET.",
["vld_as1_10_02"] = "DEPREMDEN SONRA AYAKTA AZ DUVAR KALDI... BUNLAR OLMAK ZORUNDAYDI. PATLATIN LANET ŞEYLERİ.",
["vld_as1_10_03"] = "DUVAR GİBİ KÜÇÜCÜK BİR ŞEYİN ÖNÜNÜZÜ KESMESİNE İZİN VERMEYECEKSİNİZ, DEĞİL Mİ?",
["vld_as1_11_01"] = "HARİKA. İLK KAMYON BOŞALTILDI. SIRTLARINIZ NASIL?",
["vld_as1_11_02"] = "AH, İLK KAMYON BOŞALDI. GÜZEL MANZARA. KASALAR ÇOK AĞIR DEĞİL, DEĞİL Mİ?",
["vld_as1_12_01"] = "KAÇ KASA ETTİ? DÖRTTE BİRİ Mİ? DEVAM EDİN.",
["vld_as1_12_02"] = "KASLARINIZIN AĞRIDIĞINI BİLİYORUM AMA O KASALARI KALDIRMAYA DEVAM EDİN.",
["vld_as1_12_03"] = "KASALAR AĞIR, EVET BİLİYORUM AMA İYİ EGZERSİZ.",
["vld_as1_13_01"] = "KASALARIN YARISI KAMYONLARDAN ÇIKTI. YARILADIK!",
["vld_as1_13_02"] = "ŞİMDİ GEVŞEMEYİN, TAMAM MI? ",
["vld_as1_13_03"] = "GÜZEL, GÜZEL.",
["vld_as1_14_01"] = "KOLLARINIZ BACAKLARINIZ ŞİMDİ BAĞIRIYORDUR. AMA O KASALARI ALMAYI BIRAKIRSANIZ DAHA ÇOK BAĞIRIR.",
["vld_as1_14_02"] = "ÇOK YAKLAŞTINIZ. KASALARIN DÖRTTE ÜÇÜ KAMYONDAN ÇIKTI GİBİ. DEVAM EDİN! SİZE İNANIYORUM!",
["vld_as1_14_03"] = "GÜZEL, GÜZEL. ŞİMDİ PES ETMEYİN.",
["vld_as1_15_01"] = "ARABALARLA ÇIKARMAYI RİSKE ATMAYACAĞIM. PİLOT GERİ GELİYOR AMA TOZ VE DUMANDAN SİZİ GÖREMİYOR. ONA İŞARET FİŞEĞİ YAKIN!",
["vld_as1_15_02"] = "YOLLAR AMBULANS GİBİ GEREKSİZ ŞEYLERLE, ÖYLE BOKLARLA TIKANMIŞ. SİZİ UÇURARAK ÇIKARIYORUZ. PİLOTUN GÖRMESİ İÇİN İŞARET FİŞEĞİ YAKIN.",
["vld_as1_15_03"] = "O KASALAR BU YOLLARDA RİSKE ATILAMAYACAK KADAR DEĞERLİ, HELİKOPTER GÖNDERİYORUM. MESELE ŞU, PİLOT BİR BOK GÖREMİYOR. ONA İŞARET FİŞEĞİ BIRAKMANIZ GEREK.",
["vld_as1_16_01"] = "HADİ, NE SİKİM BEKLİYORSUNUZ? KAMYONA BİNİN!",
["vld_as1_16_02"] = "KASALAR YÜKLENDİ AMA SİZ YÜKLENMEDİNİZ. VLAD BUNA ÜZÜLÜYOR, ÜZGÜN VLAD DE SİNİRLENİYOR!",
["vld_as1_16_03"] = "HEPİNİZ KAMYONA BİNİN. İÇERİDE KURABİYE VE ŞEKER VAR, SÖZ.",
["vld_as1_17_01"] = "SİZE GÜVENEBİLECEĞİMİ BİLİYORDUM, DOSTLARIM!",
["vld_as1_17_02"] = "KALİFORNİYA RÜYALARI DOSTLARIM! PARA, GANİMET, SİLAH VE... HARİKA BİR GÜN!",
["vld_as1_17_03"] = "DOĞA ANA BİLE VLAD'İ YA DA PAYDAY GANG'İ DURDURAMADI!",
["vld_as1_cbf_01_01"] = "BATI YAKASI'NIN EN BÜYÜK SUÇ ÖRGÜTÜYLE KASALARINI DOĞU YAKASI'NDA SATMAK İÇİN ANLAŞTIM. NE YAZIK Kİ İLK KASA SEVKİYATI KÜÇÜK BİR SORUNLA KARŞILAŞTI: SİKTİĞİMİN DEPREMİ! İNANABİLİYOR MUSUNUZ!? ORAYA GİDİP KASALARIN KURTARILMASINI SAĞLAYIN. KALİFORNİYA'YI SİKEYİM.",
["vld_as1_cnc_01_01"] = "DOSTLAR, MASRAFLARI KARŞILANMIŞ LA GEZİSİNE NE DERSİNİZ? GÜZEL, DEĞİL Mİ?! BİR DE HAZIR ORADAYKEN...",
["vld_as1_cnc_01_02"] = "DOSTLARIM. SİZE UFAK BİR LOS ANGELES GEZİSİ ISMARLAMAK İSTİYORUM. BELKİ ORADA BENİM İÇİN UFAK BİR İŞ YAPARSINIZ, OLUR MU?",
["vld_as1_cnc_01_03"] = "CANIM DOSTLARIM. LA'DE UFAK SORUNUM VAR. BÜYÜK BİR ŞEY DEĞİL. KÜÇÜK SORUN. BENİM İÇİN ÇÖZERSİNİZ, DEĞİL Mİ?",
["vld_bex_01_01"] = "ONLARA O BOKU ANLATMAN MI GEREK? NE BUNLAR, BEBEK GİBİ Mİ DAVRANIYORSUN?",
["vld_bex_01_02"] = "BİTİRİNCE BİRAZ TORTİLLA GETİRİN DE MANGAL FALAN YAPALIM. SPUTNİK'LERİ VLAD HAZIRLAYACAK!",
["vld_bex_01_03"] = "BANA DA BİRAZ CHİMİCHANGA FALAN GETİRİN!",
["vld_bex_02_01"] = "MEXİCO'DA KATIRIN ÇENE KEMİĞİNİ ÇALDIĞINIZ BİR MÜZİK ALETİ VAR! İNANABİLİYOR MUSUNUZ!? HAH! O ÜLKEYE BAYILIYORUM LAN!",
["vld_bex_03_01"] = "GÖZÜM ÜZERİNİZDE OLACAK. BU İŞ VLAD İÇİN ÖNEMLİ.",
["vld_bex_04_01"] = "SİZCE MEKSİKA'DA ÇOK KEÇİ VAR MIDIR?",
["vld_bex_05_01"] = "ŞU SIRALAR WASHINGTON'DA BİR SÜRÜ BOK DÖNÜYOR.",
["vld_bex_06_01"] = "YİNE Mİ HAYVANLAR? HAYVANLARLA DERDİN NE SENİN? KİMİN UMURUNDA?",
["vld_bex_07_01"] = "İYİ Kİ VLAD KULLANMANIZ İÇİN O TERMİTİ GÖNDERMİŞ, HA!",
["vld_bex_07_02"] = "BU, ÖYLE MALZEME DEĞİL; BU NANO-TERMİT! BENİM İÇİN İSVEÇ'TEN KAÇIRILDI. EKSTRA GÜÇLÜ.",
["vld_bex_08_01a"] = "BİRKAÇ YIL ÖNCE BANKAYA BİR KERE GİTMİŞTİM. BANKA MÜDÜRÜ APTAL. GİRİŞ ANAHTARINI KİŞİSEL BİR KASADA TUTUYOR AMA NEREDE OLDUĞUNU HATIRLAMIYORUM.",
["vld_bex_08_01b"] = "BİRKAÇ YIL ÖNCE BANKAYA BİR KEZ GİTTİM. MÜDÜR APTAL. ERİŞİM ANAHTARINI ŞAHSİ KASASINDA TUTUYOR AMA NEREDE HATIRLAMIYORUM.",
["vld_bex_08_01c"] = "BİRKAÇ YIL ÖNCE BANKAYA BİR KEZ GİTTİM. MÜDÜR APTAL. ERİŞİM ANAHTARINI ŞAHSİ KASASINDA TUTUYOR AMA NEREDE HATIRLAMIYORUM.",
["vld_bex_09_01"] = "NE BU KADAR UZUN SÜRÜYOR?",
["vld_bex_09_01a"] = "BU NE LAN, OLAY YERİ İNCELEME DİZİSİ FALAN MI?\n\n\n",
["vld_bex_09_01b"] = "BU NE, BİR TÜR OLAY YERİ DİZİSİ BOKU MU?\n\n\n",
["vld_bex_09_01c"] = "BU NE, BİR TÜR OLAY YERİ DİZİSİ BOKU MU?\n\n\n",
["vld_bex_10_01a"] = "İĞRENÇ, KULLANILMIŞ KAHVE FİNCANLARIYLA FALAN KOŞTURMAK!\n",
["vld_bex_10_01b"] = "İĞRENÇ, KULLANILMIŞ KAHVE BARDAKLARIYLA FALAN KOŞTURMAK!\n",
["vld_bex_10_01c"] = "İĞRENÇ, KULLANILMIŞ KAHVE BARDAKLARIYLA FALAN ETRAFTA KOŞTURMAK!\n",
["vld_bex_11_01"] = "VLAD'IN GENÇLİĞİ GİBİ AMA ÇOK DAHA AZ ATEŞ EDİLİYOR. İNANILMAZ, HENÜZ KİMSE ÖLMEDİ.",
["vld_bex_11_02"] = "ESKİ MAHALLEMDE HAVAYA ATEŞ EDERDİK, BÜTÜN SOKAKLAR BOŞALIRDI. ÇOK ETKİLİ.\n",
["vld_bex_12_01a"] = "SIÇTIK, BİR ŞEY UNUTTUM. O KASA DAİRESİNDE KASET BULURSANIZ ONLARI DA ALIN LÜTFEN... ŞEY, BEN... BİLMİYORUM, BELKİ... BELKİ SONRA BİR YERDE YAKARSINIZ, TAMAM MI?",
["vld_bex_12_01b"] = "AH SİKTİR, SİKTİR, BİR ŞEY UNUTTUM. DİNLEYİN, KASET BULURSANIZ ONLARI DA ALIN LÜTFEN... NE BİLEYİM, BELKİ SONRA BİR YERDE YAKARSINIZ, OLUR MU?",
["vld_bex_12_01c"] = "AH, SIÇTIK! SIÇTIK! BİR ŞEY UNUTTUM. DİNLEYİN, O KASA DAİRESİNDE KASET BULURSANIZ ONLARI DA ALIN LÜTFEN... BEN, ŞEY... BELKİ SONRA BİR YERDE YAKARSINIZ, TAMAM MI?",
["vld_bex_13_01a"] = "ACELE EDİN, MALLARIMIN SAĞLAM OLDUĞUNU GÖRMEK İSTİYORUM.",
["vld_bex_13_01b"] = "ACELE EDİN, MALIM İYİ DURUMDA MI GÖRMEK İSTİYORUM.",
["vld_bex_13_01c"] = "ACELE EDİN, ACELE EDİN. MALLARIMIN İYİ OLDUĞUNU GÖRMEK İSTİYORUM.",
["vld_bex_14_01a"] = "AH, GÜZEL MALIM ORADA! ALIN, ALIN!",
["vld_bex_14_01b"] = "AH, GÜZELİM MALLARIM ORADA! GÜZEL, GÜZEL, ÇOK GÜZEL. AH, BU VLAD'İ ÇOK MUTLU EDİYOR. AHH, ALIN, ALIN, ALIN, ALIN!",
["vld_bex_14_02"] = "AH, ŞEY... SADECE... BİLİRSİNİZ, BİRAZ MÜCEVHER FALAN.",
["vld_bex_14_03"] = "ŞEY, ESKİ AKRABALARA AİTTİ, AİLE YADİGÂRLARI, BİLİRSİNİZ?",
["vld_bex_15_01"] = "AH, KIYMETLİLERİM ORADA! ACELE EDİN, ACELE EDİN, ALIN ONLARI!",
["vld_bex_15_02"] = "ROMANOV'LARI BİLİYORSUNUZ, HA?",
["vld_bex_15_03"] = "ALDIĞINIZ... ESKİ AİLE ŞEYİ. ALDIRMAYIN... ÇIKARIN ORADAN YETER!",
["vld_bex_16_01"] = "ÇOK GÜZEL BİR SORU LOCKY...",
["vld_bex_16_01a"] = "MERAK ETMEYİN DOSTLARIM, VLAD YARDIM AYARLADI!",
["vld_bex_16_01b"] = "TAMAM MİLLET, VLAD SİZE BANKAYA GİRİŞ YOLU AYARLADI.",
["vld_bex_16_02"] = "BU... ESKİ AİLE MESELELERİ. SİZ ONA BAKMAYIN...",
["vld_bex_16_02a"] = "KAYINBİRADERİM. HATIRLIYORSUNUZ, DEĞİL Mİ? YARDIM ETMEK İÇİN CHİHUAHUA'DAKİ PARTİDEN GELDİ!",
["vld_bex_16_02b"] = "KAYINBİRADERİMİ HATIRLIYOR MUSUNUZ? SİZE EL ATMAK İÇİN CHİHUAHUA'DAN GELİYOR.",
["vld_bex_17_01"] = "HARİKA OLACAK... YAKINDA ORADA.",
["vld_bex_17_02"] = "MERAK ETMEYİN, İYİ OLACAK. AH! İŞTE GELİYOR! ",
["vld_bex_18_01"] = "VAY BE, GERÇEKTEN İŞE YARAYACAĞINI SANMIŞTIM!",
["vld_bex_18_02"] = "OO... BU... OYOYOYOY... BU PEK İYİ GÖRÜNMÜYOR.\n",
["vld_bex_19_01"] = "ÖLDÜ MÜ? HAY SIÇ... ÖLDÜYSE KARIM AKŞAM YEMEĞİNDE BAŞIMIN ETİNİ YER.",
["vld_bex_19_02"] = "HEY, SİKİK! UYAN. KARTELLER KAMYONU ÇALMADAN ÇIK ORADAN!",
["vld_bex_20_01a"] = "MİLLET, KAYINBİRADERİME GAZA BASMASINI SÖYLESENİZ İYİ OLUR!",
["vld_bex_20_01b"] = "HEY HEY HEY MİLLET, MİLLET! KAYINBİRADERİME GAZA BASMASINI SÖYLESENİZ İYİ OLUR!",
["vld_bex_20_01c"] = "HEY MİLLET, KAYINBİRADERİME GAZA BASMASINI SÖYLESENİZ İYİ OLUR!",
["vld_bex_21_01"] = "AH, İŞTE GİDİYOR. HAHAHA, GÜZEL.",
["vld_bex_21_02"] = "YOO, İYİ OLUR O.\n",
["vld_bex_22_01"] = "BEN, ANLAMIYORUM. NEDEN BİLGİSAYARLARA SIZMIYORSUNUZ?",
["vld_bex_23_01"] = "SORUN ÇIKARIRSA BİRKAÇ PARMAĞINI KIRIN.",
["vld_bex_23_02"] = "NEDEN OLMASIN? ETKİLİ!",
["vld_bex_24_01"] = "NEDEN ONU GEZDİRİP DURUYORSUNUZ? KAFASINA MARAKAS FALAN VURUN, KONUŞUR.",
["vld_bex_24_02"] = "HÂLÂ KAFASINA BİR DARBENİN DAHA İYİ İŞ GÖRECEĞİNİ DÜŞÜNÜYORUM.",
["vld_bex_25_01"] = "ÖF, BU ADAM NE KADAR YAVAŞ?\n",
["vld_bex_26_01"] = "NE BÜYÜK... MATKAP.",
["vld_bex_27_01a"] = "NİYE BU KADAR UZUN SÜRÜYOR?",
["vld_bex_27_01b"] = "ÖF, NİYE BU KADAR UZUN SÜRÜYOR?",
["vld_bex_28_01"] = "BEN... SİZE SÖYLÜYORUM. EN İYİ MATKAPLARI UKRAYNA YAPAR. BİR DAHAKİNE ORADAN AL LOCKY, BOZULMAZ.",
["vld_bex_29_01"] = "ATEŞ ETMEYE BAŞLAYIN, İNSANLARI ÖYLE HAREKETE GEÇİRİRSİNİZ!",
["vld_bex_30_01"] = "ŞİMDİ BU BOK DA NE?\n",
["vld_bex_30_02"] = "BİLİYOR MUSUNUZ, BU MEKSİKA POLİSLERİ GÖRÜNDÜKLERİNDEN DAHA AKILLI.\n",
["vld_bex_30_03"] = "KAFALARINA VURMALISINIZ.",
["vld_bex_end_01"] = "MUHTEŞEM DOSTLARIM. TEŞEKKÜRLER. BU İŞLERDE VLAD'A YARDIM ETTİĞİNİZ İÇİN TEŞEKKÜRLER. COYOPA'LAR ÇOK KIZACAK AMA SİKİMDE DEĞİL. ÖNEMLİ DEĞİL. ONLARLA İLGİLENME VAKTİ SONRA GELECEK. YAKINDA SİZE ULAŞACAĞIM. ORALARDA YAPACAĞINIZ DAHA ÇOK İŞ VAR.",
["vld_bex_intro_01_00"] = "HEY! HEEY! HEY HEY HEEEY! LOCKY!",
["vld_bex_intro_01_01"] = "EH, BEN, BEN, YARDIM İÇİN BURADAYIM. BU BOK ÇOK ÖNEMLİ, DOĞRU YAPTIĞINIZDAN EMİN OLMALIYIM.\n",
["vld_bex_intro_01_02"] = "MERAK ETME LOCKY, VLAD SPUTNİK'LERİNİ İÇERKEN FARE GİBİ SESSİZ OLUR!",
["vld_bex_intro_02_01"] = "HEY! HEEY! HEY HEY HEEEY! LOCKY!",
["vld_bex_intro_02_02"] = "HEY, VLAD UKRAYNALI, RUS DEĞİL!",
["vld_bex_intro_02_03"] = "BU İŞ BENİM İÇİN ÇOK ÖNEMLİ. BATIRMADIĞINIZDAN EMİN OLMAK İÇİN BURADAYIM, TAMAM MI?",
["vld_bex_intro_02_04"] = "NE ŞOFÖRÜ? NE DİYORSUN, SADECE BİRAZ TAVSİYE VERİYORUM.",
["vld_bex_intro_02_05"] = "NE PİLOTU? BEN SADECE TAVSİYE VERİYORUM. HEY, BİRAZ FAZLA HIZLI GİTMİYOR MUSUN?",
["vld_can_01_01"] = "HO HO HO, KALTAKLAR!",
["vld_can_01_02"] = "MUTLUUUUUU NOELLER!",
["vld_can_01_03"] = "ÇALDIRIN O SİKTİĞİMİN ÇANLARINI!",
["vld_can_02_01"] = "BU KÜÇÜK OYUNCAKÇI DÜKKÂNINI İŞLETEN SERSERİLER BUNLAR. YARAMAZ ÇOCUKLARDI. İNDİRİN VE İÇERİ GİRİN.",
["vld_can_02_02"] = "TAMAM, NOEL'İ ÇALMADAN O SERSERİLERİ İNDİRİN. SONRA ATÖLYEYE.",
["vld_can_02_03"] = "EŞKIYALAR ORADA. İNDİRİP ELFLERE GİDİN.",
["vld_can_03_02"] = "KOKAİNİ PAKETLEYENLERİ ARAYIN. BU 'ELFLER', OYUNCAKLARI SİKTİĞİMİN NOEL BABA'SI İÇİN YAPTIKLARINI BİLSİN! BENİM İÇİN! TAMAM MI?",
["vld_can_03_03"] = "ŞİMDİ OYUNCAKÇIDA ELFLERİ ARAYIN. ARTIK BANA OYUNCAK YAPTIKLARINA İKNA EDİN. OYUNCAK DERKEN DE BOK GİBİ ÇOK KOKAİN DEMEK İSTİYORUM!",
["vld_can_04_01"] = "POLİSLER GELİYOR! NOEL'İN İÇİNE ETMEYE. DURDURUN ONLARI, PİÇ ELFLERİN DE KAYTARMADIĞINDAN EMİN OLUN.",
["vld_can_04_02"] = "NOEL'İMİN İÇİNE ETMEYİ HEP BİRİ İSTER! POLİSLER GELİYOR. ELFLERİ MAHVETMELERİNE İZİN VERMEYİN, TAMAM MI?",
["vld_can_04_03"] = "LANET POLİSLER. NOEL'İN SİKİK HAYALETİ BUNLAR! HALLEDİN! ELFLERİ KORUYUN! NE PAHASINA OLURSA OLSUN ELFLERİ KORUYUN!",
["vld_can_05_01"] = "GÜZEL! PEKİ HEDİYELER NEREYE GİDER? BACADAN İÇERİ!",
["vld_can_05_02"] = "NOEL BABA'NIN HEDİYE NASIL GETİRDİĞİNİ BİLİYORSUNUZ, DEĞİL Mİ? O PAKETLERİ BACAYA.",
["vld_can_05_03"] = "HARİKA. KIŞ HARİKALAR DİYARI GİBİ, DEĞİL Mİ? EVET! ŞİMDİ LÜTFEN KOKAİN ÇANTALARINI BACAYA ATALIM.",
["vld_can_06_01"] = "BIRAK KAR YAĞSIN, KAR YAĞSIN, KAR YAĞSIN...",
["vld_can_06_02"] = "VLAD İÇİN BİR BEYAZ NOEL DAHA!",
["vld_can_06_03"] = "KESTANELER AÇIK ATEŞTE KAVRULUR, JACK FROST BURNUNA TOZ ÇEKER...",
["vld_can_06_04"] = "MADEM HEDİYE VERME MEVSİMİ, İŞTE SİZE KÜÇÜK BİR ŞEY.",
["vld_can_06_05"] = "VLAD'İ MUTLU ETTİNİZ. ALIN, BU SİZİN!",
["vld_can_06_06"] = "USLU KÜÇÜK SOYGUNCULAR OLDUNUZ. ALIN, BİR HEDİYE.",
["vld_can_07_01"] = "HEY! ÜRETİM DÜŞÜYOR GİBİ. GİDİP O ELFLERİ UNUTAMAYACAKLARI BİR DİLLE SİKİN! YANİ BAĞIRIN!",
["vld_can_07_02"] = "ELFLER YAVAŞLIYOR. GİDİP SUNDUĞUMUZ DİŞ BAKIM PLANINI ANLATIN. DAHA ÇOK ÇALIŞIN, YOKSA SİKTİĞİMİN DİŞLERİNİZİ KIRARIZ!",
["vld_can_07_03"] = "ELFLERE DAHA ÇOK ÇALIŞMALARINI SÖYLEYİN, YOKSA ÇORAPLARINDA BULACAKLARI TEK ŞEY GÖTLERİNE GİREN YUMRUĞUM OLACAK!",
["vld_can_07_04"] = "ŞURADA İŞTEN KAYTARAN BİR ELF Mİ VAR? GİDİP SÖYLEYİN, BURADA TEK TOPLU SÖZLEŞME BENİM ALEV MAKİNEMLE ONUN TAŞAKLARININ BİRLEŞMESİ!",
["vld_can_07_05"] = "HEY, O ELFLERİ ÇALIŞTIRIN! PERFORMANS ÖDÜLÜ ÖNERİN. İŞİ YAPARLAR, BEN DE DERİLERİNİ YÜZMEM.",
["vld_can_07_06"] = "O ELFLER VAR GÜÇLERİYLE ÇALIŞIYOR MU? BELKİ ONLARI 'MOTİVE' EDEBİLİRSİNİZ?",
["vld_can_07_07"] = "O SİVRİ KULAKLI PİÇLER YILBAŞINI GÖRMEK İSTİYORSA DAHA SIKI ÇALIŞSIN. SÖYLEYİN ONLARA!",
["vld_can_07_08"] = "O ELFLERE NOEL'İN ASIL ANLAMINI HATIRLATIN. SİLAH ZORUYLA UYUŞTURUCU ÜRETİMİ!",
["vld_can_08_01"] = "ÖLMÜŞLER. HEPSİ. BÜTÜN ELFLER. ÖLÜ. NE BİÇİM NOEL HİKÂYESİ BU LAN?",
["vld_can_08_02"] = "BÜTÜN ELFLER ÖLDÜ MÜ? SİKTİR. NOEL İPTAL DOSTLARIM.",
["vld_can_08_03"] = "OYUNCAK KASABASINDA ÜZÜCÜ BİR GÜN. BÜTÜN ELFLER ÖLDÜ. TAM REN GEYİĞİNİN SİKİNİ EMMELİK DURUM.",
["vld_can_09_01"] = "TAMAM, DC'Yİ PARTİDE TUTMAK İÇİN GEREKEN BU KADAR! AMA BALTİMORE, HARRİSBURG, PHİLLY DE VAR. SİZ YAPMAYA DEVAM EDİN, BEN ALMAYA, DOĞU YAKASI DA DANS ETMEYE DEVAM ETSİN, HA? YA DA GİDEBİLİRSİNİZ.",
["vld_can_09_02"] = "NOEL'İ NEŞELİ GEÇİRMEYE YETER BU. AMA ELFLERİN GÜZELLİK ÜRETMEYE DEVAM ETMESİNİ İSTERSENİZ BEN BİRAZ DAHA NEŞE DAĞITIRIM, ANLIYORSUNUZ YA? YA DA GİDEBİLİRSİNİZ. SİZE KALMIŞ.",
["vld_can_09_03"] = "EH, KAÇABİLİRSİNİZ TABİİ, SORUN DEĞİL. YA DA... BİR FİKİR VAR. KALIP DAHA FAZLA ELFE ZORBALIK EDEBİLİR, DAHA GÜZEL KAR YAPABİLİRSİNİZ!",
["vld_can_10_01"] = "TAMAM, SON ELF DE RAFTAN DÜŞTÜ, EVET. SİKTİR EDİN ONU. GİTME VE NOEL İKRAMİYENİZİN TADINI ÇIKARMA VAKTİ, DOSTLAR!",
["vld_can_10_02"] = "AHHH, SON ELF DE ÖLDÜ. ÜZGÜN MÜYÜM? HAYIR, SİKTİR EDİN ELFİ. OYUNCAKLARI ALDIK, GİTME VAKTİ.",
["vld_can_10_03"] = "VEEE... SON ELF DE GİTTİ. ÜZÜCÜ AMA GÖREVLERİNİ YAPTILAR. BİZ DE İSTEDİĞİMİZİ ALDIK. GİTME VAKTİ DOSTLAR!",
["vld_can_11_01"] = "NOEL MUCİZESİ! İYİ İŞ DOSTLARIM. DÜNYADA BARIŞ OLSUN... GELECEK YILA KADAR.",
["vld_can_11_02"] = "MÜKEMMEL! İYİ İŞ. DC BU GECE PARTİ YAPACAK!",
["vld_can_11_03"] = "ALTIN, GÜNLÜK VE MÜR GETİRDİNİZ. VLAD'E MÜR... YANİ DAHA ÇOK KOKAİN!",
["vld_can_12_01"] = "ALIN, KUZENİMDEN BU HEDİYEYİ ALIN. SİZİ SICAK TUTACAĞINI SÖYLEDİ!",
["vld_can_12_02"] = "İŞİM ALMAK OLABİLİR AMA VLAD HİÇ KARŞILIK VERMEZ DEMEYİN! NOEL GELDİ AMINA KOYAYIM!",
["vld_can_12_03"] = "BUNU BİR KAPI ARALIĞINA ATIN. O YARAMAZ ÇOCUKLARI HAK ETMEDİKLERİ HEDİYELERDEN UZAK TUTMAYA YARAR!",
["vld_can_cbf_01"] = "HER NOEL KÜÇÜK BİR OPERASYON KURARIM. ÇOCUKLARA HEDİYELER, EBEVEYNLERE DE \"HEDİYELER\", DEĞİL Mİ? MESELE ŞU, BU YIL MALZEME AZ. AMA! BİR ALTERNATİF BULDUM. YAKINDA BİR AVUÇ ŞEREFSİZİN OPERASYONU VAR. KÜÇÜK OYUNCAK DÜKKÂNI GİBİ DÜŞÜNÜN. ORAYA GİDİN, KORUMALARI İNDİRİN, \"ELFLERİ\" YENİDEN İŞE KOYUN.",
["vld_can_cnc_01"] = "MUTLU NOELLER, DOSTLARIM! KÜÇÜK BİR NOEL MUCİZESİ İÇİN YARDIMINIZ GEREK.",
["vld_can_cnc_02"] = "VLAD AMCANIZ NOEL 'NEŞESİNİ' SAĞLAYAMAZSA BAŞKENTTEKİ BÜTÜN OFİS PARTİLERİ DAHA SIKICI GEÇECEK. YARDIM EDEBİLİRSİNİZ.",
["vld_can_cnc_03"] = "KÜÇÜK OYUNCAKÇILARIM SORUN YAŞIYOR SEVGİLİ DOSTLAR. YARDIM EDEBİLİR MİSİNİZ?",
["vld_chca_01_01"] = "AH, BU İLGİNÇ OLABİLİR!",
["vld_chca_01_02"] = "AH, GÜZEL! VLAD KULAK MİSAFİRİ OLMAYI SEVER!",
["vld_chca_02_01"] = "HEY, ORADA NE KADAR KOŞTURACAKSINIZ? KABİN BULMAK BU KADAR ZOR MU?",
["vld_chca_03_01"] = "MERHABA, SENİ ERİŞTE HÖPÜRDETEN BOK PARÇASI.",
["vld_chca_04_01"] = "FENA DEĞİL, FENA DEĞİL. KÜÇÜK KIZLA EJDERHANIN ÇOCUK HİKÂYESİNİ DUYDUNUZ MU?",
["vld_chca_04_02"] = "ASLINDA OLDUKÇA İYİ. GEÇENLERDE ÇİN'DEN ÇOK TATLI BİR HİKÂYE DUYDUM. BİR KIZLA EJDERHA HAKKINDA.",
["vld_chca_05_01"] = "SONUNU SÖYLEYEYİM: EJDERHA BİR DAĞIN ALTINDA EZİLİR, SONRA KÜÇÜK KIZ RUHUNUN GÜCÜYLE DAĞI PARÇALAR.",
["vld_chca_05_02"] = "ÇOK İLGİNÇ BİTİYORDU. KIZ, EJDERHAYI EZMEK İÇİN BİR DAĞ KULLANDI.",
["vld_chca_06_01"] = "SADECE SENİN İÇİN ÖZEL BİR SÜRPRİZİMİN YOLDA OLDUĞUNU BİLMENİ İSTEDİM.",
["vld_chca_06_02"] = "BİLMENİ İSTEDİM OROSPU ÇOCUĞU: VLAD UNUTMAZ. AFFETMEZ DE. KÜÇÜK EJDERHA.",
["vld_chca_07_01"] = "HAJRUDİN'İN VEGAS'TAKİ KUMARHANEDEN SLOT MAKİNESİ ÇALMAYA ÇALIŞTIĞINI ANLATMIŞ MIYDIM? SİKTİR, HİÇ HOŞ DEĞİLDİ.",
["vld_chca_08_01"] = "HEY, ŞU PİÇLERİ İNDİRİRKEN BİRAZ EĞLENELİM. KALAN PARAYA BİR BOYA BOMBASI KOYUP MAHVOLDUĞUNDA GÜZEL BİR 'SİKTİRİN GİDİN' HEDİYESİ VERMEYE NE DERSİNİZ?",
["vld_chca_09_01"] = "SAKIN YÜZEN KAPILARA BİNİP KAÇMAYA ÇALIŞMAYIN. NE? FİLMDE GÖRDÜM! O BOK İŞE YARAMADI!",
["vld_chca_10_01"] = "VLAD'E BİRKAÇ ÖZEL SPUTNİK HAZIRLATMALIYDINIZ. ONU ÇOK DAHA HIZLI İNDİRİRDİ!",
