["vld_chca_12_01"] = "İYİ BİR AMAÇ UĞRUNA PARA YAKMAK HER ZAMAN UYGUNDUR. DÜŞMANLARINI EZMEK DE ÇOK İYİ BİR AMAÇTIR.",
