["vld_chca_14_02"] = "VAY BOK PARÇASI KANG, SENİ OROSPU ÇOCUĞU! İŞTE O, İŞTE O!",
["vld_chca_15_01"] = "HEY, OROSPU ÇOCUĞU MEME UÇLARIMI ELEKTRİKLE YAKIYORDU! LANET ELİNE BAKMADIM!",
