["vld_cp1_01_01"] = "İŞTE ORADA! O İŞE YARAMAZ BOK ÇUVALINI SARSIP UYANDIRIN. HADİ OROSPU! UÇAĞIM NEDEN YANIYOR?",
["vld_cp1_01_02"] = "İŞTE ŞU... AARGH, BİR BOKA YARADIĞI YOK. KALK. KALK, SUKA BLYAD! AYAĞA KALK!",
["vld_cp1_01_03"] = "ŞU SARHOŞ PİÇE BAKIN. SURATINA SIÇASI GELİYOR İNSANIN. İŞE YARAMAZ OROSPU...!",
