["vld_cp1_02_03"] = "PİSLİK! YAĞAN KAR DEĞİL. BENİM SİKTİĞİMİN MALI. BENİM SİKTİĞİMİN MALI! SENİN YÜZÜNDEN!",
["vld_cp1_03_01"] = "AHH! O YAŞLI GÖT HERİF GERİ DÖNÜYOR. AFERİN. PAKETLERİMDEN BİRKAÇINI BULABİLİRSENİZ... VLAD ÇOK MİNNETTAR OLUR.",
