["vld_cp1_04_01"] = "HELİKOPTERE TAŞIYABİLDİĞİNİZ BÜTÜN KOKAİNİM İÇİN ÇOK İYİ PARA ÖDERİM. ÇOK İYİ!",
["vld_cp1_04_02"] = "KOKAİNİ HELİKOPTERE KOYARSINIZ, SİZİ ZENGİN EDERİM. KOYMAZSINIZ, BENİ ÜZERSİNİZ. ÜZGÜN VLAD... KÖTÜDÜR.",
