["vld_cp1_05_01"] = "AH! O SES! SANIRIM BİR PAKET DAHA DÜŞTÜ, DEĞİL Mİ?",
["vld_cp1_05_02"] = "PAKETLERİMDEN BİRİ DAHA! BULUN ONU. ",
["vld_cp1_05_03"] = "SANIRIM AZ ÖNCE BİR PAKET DAHA DUYDUM. O BENİM! ARAYIN!",
