["vld_cp1_cbf_01"] = "O PİSLİK KAYINBİRADERİM, İŞE YARAMAZ TAŞAK DERİSİ ÇUVALI, UÇAĞINI DÜŞÜRDÜ. BİR ŞEYE ÇARPMIŞ VE... POLİSLERİN ONU ALMASINA İZİN VEREMEYİZ. NORMALDE O SARHOŞ PİSLİĞİ SİKİME TAKMAM. ORADA ÇÜRÜMEYE BIRAKIRIM AMA İŞTE... AİLE. O ESKİ AYYAŞI BULUP ÇIKARIN. PAKETLERİNİN HER BİRİ İÇİN DE GÜZEL BİR NOEL İKRAMİYESİ VERİRİM.",
["vld_cp1_cnc_01"] = "KARIMIN KARDEŞİ, O PİSLİK OROSPU ÇOCUĞU, UÇAĞINI ŞEHRİN HEMEN DIŞINDAKİ ORMANA DÜŞÜRDÜ. ONU VE YÜKÜNÜ BURAYA GERİ GETİRMELİYİM. ",
