["vld_cp1_end_02"] = "DÖNDÜ VE ŞİMDİDEN İÇKİ DOLABIMI BOŞALTIYOR. LANET OLSUN. NEYSE, İYİ İŞ ÇIKARDINIZ ÇOCUKLAR. BUNU HAK ETTİNİZ.",
["vld_cp1_end_03"] = "GÜZEL İŞTİ. VE GÜZEL... SASHA! ANAHTARLARI ONDAN AL! EVET, İYİ İŞ. PRİMİ HAK ETTİNİZ.",
