["vld_fex_19a_01"] = "BU ADAM ŞU BOKA KAFAYI FENA TAKMIŞ. O SUNAK ŞEYİNE BAKMAZSAN GECE BİR İBLİS GELİP RUHUNU ALIR SANIYOR.",
