["vld_fex_26a_02"] = "SURATINA BİR KURŞUN SIKIN. VLAD'I SEVİNDİRİN!",
["vld_fex_26a_03"] = "TAMAM, ŞİMDİ VURUN ONU! VURUN O AŞAĞILIK PİÇİ!",
["vld_fex_26a_04"] = "KANINI AKITIN! ÖLÜRKEN SESİNİ DUYMAK İSTİYORUM!",
