["vld_fex_27a_01"] = "HEY, ŞİMDİ HATIRLADIM, BULUC'UN BAĞLANTI LİSTELERİNİ TUTTUĞU BİR KASASI VAR. AÇIP ALSANIZ MI, HA?",
