["vld_fex_27a_03"] = "BİLİYOR MUSUNUZ... BULUC KASASINDA BİR SÜRÜ BİLGİ TUTUYOR. AÇIP İÇİNİ BOŞALTIRSANIZ İŞE YARAYABİLİR.",
