["vld_fex_30_04"] = "ŞU COYOPA PİSLİKLERİ PARALARIYLA BİR SÜRÜ GÜZEL ARABA ALIYOR. KAÇMAK İÇİN GARAJDAN BİRİNİ ÇALABİLİRSİNİZ.",
