["vld_fex_43a_01"] = "PATLAYICILARI ALIP BULUC'TA KULLANAMAMANIZ YAZIK. ŞU SCANNER FİLMİNDEKİ GİBİ KAFASINI PATLATIN! NEYSE. BAŞKA BİR ŞEKİLDE ACI ÇEKTİRİN!",
["vld_fex_43a_02"] = "ŞİMDİ ÇOK GEÇ TABİİ AMA BULUC'UN KAFASININ O FİLMDEKİ GİBİ PATLADIĞINI GÖRMEK EĞLENCELİ OLURDU... JAMMER... SPAMMERS... ADI HER NEYSE.",
["vld_fex_50_01"] = "ESKİ GÜNLER DAHA EĞLENCELİYDİ. SİLAH, BALTA VE BELKİ DİZ KAPAKLARI İÇİN GÜZEL BİR MATKAP YETERDİ. VLAD ŞU SIZMA BOKUNU HİÇ ANLAMAYACAK.",
["vld_fex_50_02"] = "SÖYLEYEYİM, VLAD BU SİSTEM KIRMA BOKUNU HİÇ SEVMEYECEK. KORKAKÇA GELİYOR. BİLGİ İSTEDİĞİNDE YA DA BİR YERE GİRMEK GEREKTİĞİNDE İYİ BİR BEYZBOL SOPASI YETER.",
["vld_fex_50_03"] = "AH, YİNE ŞU SIZMA İŞİ. DAHA FAZLA BİLGİSAYAR BOKU. BİLEN BİRİNİ BULUN, KOLUNU MENGENEYE KOYUN, İSTEDİĞİNİZ HER ŞEYİ YAPAR!",
["vld_fex_52e_01"] = "EVİNİN BİR YERİNE \"MABET\" ADINI NASIL BİR \"KİBİRLİ GÖT\" VERİR?",
