["vld_fex_57_01"] = "O BOK PARÇASINI OKYANUSA DÜŞÜRÜN!",
["vld_fex_57_02"] = "BOK PARÇASINI VURUN! BENİM İÇİN EL SALLAYIN!",
["vld_fex_57_03"] = "VURUN! DİZİNDEN VURUN! YOK YOK YOK, KARNINDAN! SONRA AŞAĞI DÜŞÜRÜN.",
["vld_fex_57_04"] = "SİLAHLARINIZI KULLANIN! OKYANUSA DÜŞÜRÜN DE BOĞULSUN!",
["vld_fex_57_05"] = "BU GERİLİM VLAD'İ ÖLDÜRÜYOR! YAPIN, YAPIN!",
["vld_fex_57a_01"] = "AH, SABIRSIZLANIYORUM! HEY MİLLET, BULUC KURŞUNUN BENDEN GELDİĞİNİ BİLSİN, TAMAM MI?",
["vld_fex_57a_02"] = "ŞİMDİ BU BOK PARÇASI VLAD'İN ONA VERMEK İSTEDİĞİ ŞEYİ ALACAK!",
["vld_fex_57a_03"] = "HEY LOCKY... HARİKA! AL, BİRAZ PATLAMIŞ MISIR!",
["vld_fex_57b_01"] = "DOSVEDANYA, OROSPU ÇOCUĞU!",
["vld_fex_57b_02"] = "AL BAKALIM, OROSPU ÇOCUĞU!",
["vld_fex_57b_03"] = "BRAVO! İYİ YÜZMELER BOK PARÇASI!",
["vld_fex_57b_04"] = "KÜÇÜK BALIKLARA SELAM SÖYLE!",
["vld_fex_57c_01"] = "UKRAYNA'DA ESKİ SÖZ VARDIR. İNTİKAM, KÖPEK BALIKLARININ YEMESİ GEREKEN YEMEKTİR.",
["vld_fex_57c_02"] = "GAZETEDE KÖPEK BALIKLARININ NEREDEYSE HİÇ İNSAN ÖLDÜRMEDİĞİNİ OKUDUM. AMA İŞTE, HA?",
["vld_fex_57c_03"] = "HAY SIÇAYIM. ÇOK KAN AKTI! ACABA NE KADAR ACIDI?",
["vld_fex_57c_04"] = "CİNSEL ORGANLARI BİR BALIĞIN MİDESİNE GİDERKEN İNSAN NE DÜŞÜNÜR, MERAK ETMEDEN DURAMIYORSUN.",
["vld_fex_57c_05"] = "KENDİ KÖPEKBALIĞI TARAFINDAN YENİLEN BİR ADAM EN SON NE DÜŞÜNÜR SİZCE?",
["vld_fex_57c_06"] = "KÖPEKBALIĞI PİS COYOPA AVINA ÇIKTI!",
["vld_fex_58_01"] = "YAPIN ARTIK, İNDİRİN ONU!",
["vld_fex_58_02"] = "VLAD HÂLÂ KAN GÖRMEYİ BEKLİYOR!",
["vld_fex_58_03"] = "TAM ORADA! BEDELİNİ ÖDETİN!",
["vld_fex_58a_01"] = "HEY, GİTMEDEN ÖNCE... O SİKİKİN KASASINI AÇIN. İÇİNDE ÇOK ŞEY VAR! BAĞLANTILAR, PARA... SÖZLEŞMELER. ÇOK FAYDALI!",
["vld_fex_58a_02"] = "VLAD ŞİMDİ HATIRLADI! BULUC BÜTÜN BAĞLANTILARINI VE İŞ BİLGİLERİNİ BİR KASA'DA TUTUYOR. AÇIP İÇİNİ BOŞALTIN!",
["vld_fex_58a_03"] = "VAY... PEKİ. DURUN! BULUC'UN KASASI... BÜTÜN BAĞLANTILARI VE ANLAŞMALARI İÇİNDE. AÇABİLİRSENİZ ELİMİZDE BULUNMASI İYİ OLUR!",
["vld_fex_58b_01"] = "KASANIN İÇİNDEKİNİ İSTİYORUM!",
["vld_fex_58b_03"] = "O KASA'NIN İÇİNDEKİLERDEN ÇOK PARA KAZANILIR.",
["vld_fex_59a_01"] = "HASSİKTİR. KIZGIN GÖRÜNÜYORLAR. TIJUANA FEDERALLERİNE ARTIK UYUŞTURUCU PARASI YOK, HA?",
["vld_fex_59a_02"] = "FEDERALLERİN TEK KARTEL PATRONU İÇİN BU KADAR ÖFKELENMESİNİ BEKLEMEZDİM. ONLARA ÇOK PARA VERMİŞ OLMALI!",
["vld_fex_59a_03"] = "BULUC'U ÖLDÜREREK FEDERALLERİN EN BÜYÜK PARA ÇUVALINI ELLERİNDEN ALDINIZ! PEK MUTLU GÖRÜNMÜYORLAR!",
["vld_fex_end_01"] = "BİR KEZ DAHA, DOSTLARIM, BANA BÜYÜK HİZMET ETTİNİZ. BULUC ARTIK BALIKLARIN BOKUNA DÖNÜŞTÜĞÜNE GÖRE COYOPA'LARIN İŞİ BİTTİ SANIYORUM. DENTİST'İN DE MEKSİKA'DA YARDIMI KALMADI, ÇARESİZ VE SAVUNMASIZ OLACAK. SIRADAKİ İŞİNİZ HER NEYSE SİZE DAHA KOLAY GELMELİ. VLAD'İ UNUTMAYIN YETER, TAMAM MI? ÇOK ŞEY OLUYOR, İLERİDE BİZİM İÇİN TEHLİKELİ OLABİLECEK ŞEYLER. AMA DAHA ÇOK KONUŞACAĞIZ... YAKINDA. ŞEREFE, HOŞÇA KALIN.",
["vld_fex_end_02"] = "BUGÜN İYİ BİR ŞEY YAPTINIZ DOSTLARIM. SANIRIM COYOPA'LARIN İŞİ BİTTİ VE DENTİST, MEKSİKA'DAKİ BÜTÜN NÜFUZUNU KAYBEDECEK. ARTIK ORADAN ONA YARDIM GELMEYECEK. BUNU HAJRUDİN'E ANLATACAĞIM, SEVİNECEK. BELKİ BİRAZ DA KENDİNE ÇEKİ DÜZEN VERİR. BELKİ DE VERMEZ. ARTIK VLAD SİZE BORÇLU VE ÇOK YAKINDA KARŞILIĞINI VERECEĞİM. ŞİMDİ İLGİLENMEM GEREKEN YENİ İŞLER VAR. TEKRAR GÖRÜŞENE DEK! ŞEREFE, HOŞÇA KALIN.",
["vld_fex_intro_01_01a"] = "VLAD BU BOKTAN İŞTE ONA YARDIM EDECEĞİNİZ İÇİN ÇOK MUTLU.",
["vld_fex_intro_01_02"] = "GÜZEL, GÜZEL. AMA GERÇEKTEN DAHA İYİ EKİPMAN ALMALISIN! BUNLAR ESKİ, ÇÖZÜNÜRLÜĞÜ DÜŞÜK. HİÇBİR BOK GÖREMİYORUM!",
["vld_fex_intro_01_02a"] = "VLAD O PİÇ BULUC İNDİRİLİRKEN GÖZLERİNDEKİ KORKUYU GÖRMEK İSTİYOR, TAMAM MI?\n",
["vld_fex_intro_01_03"] = "ONU YAPARSAN BELKİ BİRKAÇ KİŞİ TANIRIM. SENİ GÖRÜŞTÜRÜRÜM!\n",
["vld_fex_intro_02_01"] = "OO, VLAD ADAM GİBİ ESKİ USUL İNTİKAM ALMAYALI ÇOK OLDU. O AŞAĞILIK BULUC, KEŞKE İSVİÇRE'DE DOĞSAYDIM DİYECEK!\n",
["vld_fex_intro_02_02"] = "BİR SÜRÜ SIĞINAKLARI FALAN VAR.\n",
["vld_fex_intro_02_03"] = "NE ANLAMI, HA? NE SİKİK ANLAMI? ŞAKAYI ANLAMADIN MI? TAMAM, ANLATAYIM.",
["vld_fex_intro_02_03a"] = "VLAD'IN ÖFKESİ... ŞEY GİBİ... KAFANA KOCAMAN, SİKİK BİR NÜKLEER BOMBA DÜŞMESİ GİBİ.",
["vld_fex_intro_03_01"] = "ŞİMDİ EKİBE ACIMASIZ OLMALARINI SÖYLEMEYİ UNUTMA. BULUC'A İYİCE ACI ÇEKTİRSİNLER.\nBELKİ JIRO SAMURAY KILICIYLA TAŞAKLARINI KESER FALAN.",
["vld_fex_intro_03_02"] = "TAMAM... BULUC'U ÖLDÜRÜRKEN OROSPU ÇOCUĞUNUN İYİCE ACI ÇEKTİĞİNDEN EMİN OLUN.\n",
["vld_fex_intro_04_01"] = "VLAD BU İŞİ YAPTIĞINIZ İÇİN MİNNETTAR. BU BOK BİTİP BULUC ÖLÜNCE GERÇEK İŞE DÖNERİZ, DEĞİL Mİ?",
["vld_fex_intro_04_01a"] = "BELKİ BAIN'E NE OLDUĞUNU, SONRA NE PLANLADIĞINIZI BANA ANLATIRSIN?\n",
["vld_fex_intro_04_02"] = "HEY, HEY, HEY. BUNU GEÇİŞTİRME. BAIN'LE VLAD'IN UZUN BİR GEÇMİŞİ VAR. BU BOKU ÖNEMSİYORUM.",
["vld_fex_intro_04_02a"] = "İNSANLAR DA KONUŞUP NE HALT OLDUĞUNU MERAK ETMEYE BAŞLADI.\n",
["vld_fex_intro_04_03"] = "TAMAM, TAMAM... SÖYLEDİĞİMİ UNUTMA YETER. GEÇMİŞTEKİ BOKLAR DÖNÜP PEŞİNE DÜŞEBİLİR.\n",
["vld_fex_tap01_01"] = "BULUC PARANOYAĞI DELİNİN TEKİ. DEDİĞİNİZ GİBİ HER ODADA KAMERA VE MİKROFON VAR.",
["vld_fex_tap01_02"] = "TAM DEDİĞİNİZ GİBİ. HER ODADA KAMERA VE MİKROFON. BULUC HASTA SİKİK.",
["vld_fex_tap01_03"] = "UMARIM EKRANA ÇIKMAYI SEVİYORSUNUZDUR. BULUC EVİN HER ODASINDA SES VE GÖRÜNTÜ KAYDI ALIYOR. TAM BİR KAÇIK AMINA KOYAYIM!",
["vld_fex_tap02_01"] = "HEY MİLLET... ŞUNU DİNLEYİN.",
["vld_fex_tap02_01a"] = "DUR, AKLIMA BİR FİKİR GELDİ. BİRAZ EĞLENELİM.",
["vld_fex_tap02_01b"] = "TABİİ Kİ BİLİYORUZ! DİNLEYİN...",
["vld_fex_tap02_01c"] = "DURUN, DURUN. ŞUNU DİNLEYİN...",
["vld_fex_tap02_01d"] = "[TELEFON ÇALAR]",
["vld_fex_tap02_02"] = "BULUC, ESKİ DOSTUM! NASILSIN?",
["vld_fex_tap02_02a"] = "HEY, BİL BAKALIM KİM, BOK PARÇASI! NASIL HİSSEDİYORSUN?",
["vld_fex_tap02_03"] = "AH, ÖZEL BİR ŞEY YOK. SAYGILARIMI SUNMAK İÇİN ARADIM.",
["vld_fex_tap02_03a"] = "HEY, ARAYIP SENİ NE KADAR SEVDİĞİMİ SÖYLEYEMEZ MİYİM?",
["vld_fex_tap03_01"] = "MERHABA DOSTUM.",
["vld_fex_tap03_01a"] = "MERHABA.",
["vld_fex_tap03_02"] = "AKRABAMA YAPTIĞIN O PİSLİK VAR YA. PİŞMAN OLACAKSIN.",
["vld_fex_tap03_02a"] = "KARIMIN ERKEK KARDEŞİ. ONA YAPTIĞIN BOK.",
["vld_fex_tap03_03"] = "HEY, SİKTİR GİT... BOK PARÇASI.",
["vld_fex_tap03_03a"] = "KARIMA SANA BEDEL ÖDETECEĞİME SÖZ VERDİM. UNUTMA BUNU.",
["vld_fex_tap04_02"] = "MERHABAAA ESKİ DOSTUM!",
["vld_fex_tap04_02a"] = "MERHABA DOSTUM.",
["vld_fex_tap04_03"] = "İYİ, BULUC. GAYET İYİ. BEN BİTİRİNCE SENİN OLACAĞIN GİBİ DEĞİL, HA?",
["vld_fex_tap04_03a"] = "ONU MERAK ETME. KENDİNİ DÜŞÜN.",
["vld_fex_tap05_01"] = "AH, O BOK PARÇASI VLAD'E BULAŞTIĞINA PİŞMAN OLACAK.",
["vld_fex_tap05_02"] = "HEY, BELKİ SİZ İŞİNİZİ BİTİRİNCE BU EVE BEN YERLEŞİRİM, HA?",
["vld_fex_tap05_03"] = "NE BÜYÜK İSRAF, BUNCA ALAN O MEKSİKALI BOK VE COYOPA'LARI İÇİN...",
["vld_fex_tap05_04"] = "GÜZEL EV. VLAD'IN MOBİLYALARIYLA DAHA GÜZEL GÖRÜNÜR.",
["vld_fex_tap06_01"] = "SÖYLE ESKİ DOSTUM. CEHENNEME GİTMEDEN ÖNCE ARAFTA KAÇ YIL GEÇİRECEKSİN?",
["vld_fex_tap06_01a"] = "CEHENNEME GİTMEDEN ÖNCE İNSANIN ARAF'TA VAKİT GEÇİRMESİ GEREKİRMİŞ.",
["vld_fex_tap06_02"] = "UKRAYNA'DA ESKİ SÖZ VARDIR: HER GÜNAH İÇİN 150 YIL, SONRA SONSUZA KADAR YANARSIN.",
["vld_fex_tap06_02a"] = "NE KADAR SÜRECEĞİ, KAÇ GÜNAH İŞLEDİĞİNE BAĞLI. SENİN DE GÜNAHIN ÇOK, SENİ PİÇ.",
["vld_fex_tap06_03"] = "ÇOK YAKINDA GÖRECEKSİN SEVGİLİ BULUC. GÖRECEKSİN.",
["vld_fex_tap06_03a"] = "HER ŞEY SİZİN İÇİN O DEAD HEAD VODKA GİBİ BERRAKLAŞACAK. ",
["vld_fex_tap08_01"] = "HEY LOCKY... BULUC'UN TELSİZİNE BAĞLIYIM, DEĞİL Mİ?",
["vld_fex_tap08_01a"] = "BULUC'UN TELSİZİNİ... NE DİYORSUNUZ... HACKLEDİN Mİ?",
["vld_fex_tap08_02"] = "HEY, HEY BULUC, MEKSİKALI NAZİ OĞLAN! VLAD'İN SANA UFAK BİR SÜRPRİZİ VAR!",
["vld_fex_tap08_02a"] = "NE OLUYOR EŞEK SİKEN HERİF? ESKİ DOSTUN VLAD SANA PARTİ HEDİYESİ GÖNDERİYOR!",
["vld_fex_tap08_03"] = "SANIRIM BİRKAÇ DAKİKA SONRA O KADAR GÜLMEYECEKSİN DOSTUM.",
["vld_fex_tap08_03a"] = "BEKLE DOSTUM! GELECEK ŞEY SENİ HAYAL KIRIKLIĞINA UĞRATMAYACAK, SÖZ!",
["vld_fex_tap08_03b"] = "GÖRÜNÜŞE GÖRE ÖFKELİ BİRKAÇ PALYAÇO SENİ ZİYARETE GELİYOR, ESKİ DOSTUM!",
["vld_fourstores_brf_speak_01"] = "ŞEHRE YENİ DÖNDÜM, RUS (SERSERİLER) GÖRÜYORUM. DMİTRİ'NİN ADAMLARI, BENİM BÖLGEMDE. BUNA KATLANAMAM!",
["vld_fourstores_brf_speak_02"] = "MAPLE STREET'TEKİ DÖRT DÜKKÂNDAN PARA AKIŞI BENİMDİ. DÜZENLİ GELİRİM! EKMEĞİM. ŞİMDİ SİK YALAYANIN BİRİ OPERASYONUMU ALIYOR, BANA BASIYOR. VLAD'E! HAH!",
["vld_fourstores_brf_speak_02b"] = "ORAYA GİDİP BULABİLDİĞİNİZ BÜTÜN PARAYI ALACAK, ONLARI CANLARI YANMIŞ HÂLDE BIRAKACAKSINIZ! VLAD'A YAPILANIN KARŞILIĞINI VLAD'IN VERDİĞİNİ GÖSTERİN!",
["vld_fourstores_brf_speak_03"] = "DÜKKÂNLARIMIN KASALARINDA VE PARA ÇEKMECELERİNDE NAKİT VARDI; SADIK İNSANLAR BENİM İÇİN ÇOK ÇALIŞIRDI. ŞİMDİ BAŞKA BİR RUS İÇİN ÇALIŞIYORLAR.",
["vld_fourstores_brf_speak_03b"] = "BUNU SEVMİYORUM, PARAMI DA GERİ İSTİYORUM. ORAYA GİDİP ALIN! SADAKATSİZ HEMŞERİLERE NE YAPILDIĞINI GÖSTERİN!",
["vld_fourstores_brf_speak_04"] = "HAPİSHANE İNSANI DEĞİŞTİRİR. BENDE DAHA ÇOK PARA AKIŞINI DEĞİŞTİRDİ. BİR RUS DÖRT DÜKKÂNLIK BÖLGEMİ ALDI.",
["vld_fourstores_brf_speak_04b"] = "DÜKKÂNLARI GERİ İSTEMİYORUM. PARAYI VE GÜÇ GÖSTERİSİNİ İSTİYORUM. GİDİP SERT VURUN! YAPINCA PARA SİZE GELİR.",
["vld_fourstores_cnc_01"] = "DOSTLARIM! VLAD'IN ŞU ESKİ DÜKKÂNLARIN KASALARINI DENGELEMESİNE YARDIM EDER MİSİNİZ? KÜÇÜCÜK BİR İŞ ASLINDA.",
["vld_fourstores_cnc_02"] = "İŞ İÇİN BİR SÜRE UZAKTAYDIM... İŞLETMELERDEN PARA TOPLAMAM GEREK.",
["vld_fourstores_cnc_02b"] = "BENİMKİ TABİİ.",
["vld_fourstores_cnc_03"] = "BEN İÇERİDEYKEN... GERİDE BIRAKTIĞIM PARAMI TOPLAYACAK ORTAK LAZIM.",
["vld_fourstores_debrief_01"] = "İYİ İŞ DİYORUM! HAHAHA! SİZİNLE YİNE ÇALIŞACAĞIM! AH! VLAD LANET SPUTNİK GİBİ YÜKSELİŞTE! HOH! ŞİMDİ PARTİ ZAMANI! PARTİ PARTİ! HEY!",
["vld_fourstores_debrief_02"] = "HAHAHEY! İYİ İŞ DİYORUM! HAHA! SİZİ YİNE KULLANACAĞIM! OH EVET! VLAD LANET SPUTNİK GİBİ YÜKSELİYOR! HOH!",
["vld_fourstores_debrief_03"] = "MESAJI VERDİNİZ, GÜZEL MESAJDI! SANIRIM ‘SİKTİR GİT’ DEDİNİZ, HAHA! HERKES NET DUYDU! PARA İYİYDİ. HEY! VOTKA İÇİN, HAFTA SONUNUN TADINI ÇIKARIN.",
["vld_fourstores_debrief_04"] = "YAPMAYIN! VLAD'E BULAŞMAYIN! BULAŞMAMAYI ÖĞRENİRLER! BENİM İÇİN MESAJI VERDİĞİNİZ İÇİN SAĞ OLUN, PARA DA SİZİN KEYFİNİZE. GÖRÜŞÜRÜZ!",
["vld_fourstores_debrief_05"] = "HAHA! ÇELİKTEN ADAMLAR OLDUĞUNUZU BİLİYORDUM. DENGEYİ SAĞLADIĞINIZ İÇİN TEŞEKKÜRLER! RUSLAR VLAD'I YİNE HATIRLADI! ARGH-HAHAHA! ÇOK KIZGIN AYI GİBİ, ARGH!",
["vld_ko1b_01_01"] = "NEREDE KALDINIZ PALYAÇOLAR? KASA DAİRESİ İÇİN MURKYWATER KONTEYNERLERİNİ KONTROL EDİN.",
["vld_ko1b_01_02"] = "HADİ, PARMAKLARINIZI GÖTÜNÜZDEN ÇIKARIN. KASA DAİRESİ BİR MURKYWATER KONTEYNERİNDE OLACAK.",
["vld_ko1b_01_03"] = "O MURKY PİÇLERİ GÜZEL MALLARI SEVK ETMEYE ÇALIŞACAK, KONTEYNERLERİNE BAKIN!",
["vld_ko1b_02_01"] = "AHHH! KASA DAİRESİ. SİHRİN KOKUSUNU NEREDEYSE (DERİN NEFES ALIR) ALIYORUM!",
["vld_ko1b_02_02"] = "BULDUNUZ. GÜZEL! GÜZEL. SİZE GÜVENEBİLECEĞİMİ BİLİYORDUM.",
["vld_ko1b_02_03"] = "EVET. KASA DAİRESİ! BU İYİ. BU ÇOK İYİ!",
["vld_ko1b_03_01"] = "AH, DONUNU ISLATMA BAIN! ALICIM VAR. ÇOK UZAKTA. HER ŞEY YOLUNDA. ",
["vld_ko1b_03_02"] = "SAKİN OL, KOCA BEBEK. ALICI ÇOK UZAKTA. MUHTEMELEN KULLANMAZ BİLE.",
["vld_ko1b_03_03"] = "AĞLAMA BAIN. HER ŞEY YOLUNDA. ALICI BUNLARA ÇOK PARA ÖDÜYOR. ÇOK UZAKTALAR.",
["vld_ko1b_04_01"] = "BİR TREN HAZIRLADIM. ÇOK UZAKTA DEĞİL. SAVAŞ BAŞLIKLARINI GETİRİN. ÇABUK!",
["vld_ko1b_04_02"] = "ŞİMDİ TREN SAHASINA GÖTÜRÜN. FARK ETTİKLERİNDE ÇOKTAN UZAKTA OLACAKSINIZ.",
["vld_ko1b_04_03"] = "ONLAR İÇİN BEKLEYEN BİR TRENİM VAR. YAKINDA. NÜKLEER BOMBALARI GETİRİN. ÇABUK!",
["vld_ko1b_05_01"] = "İYİ MİSİNİZ? MAKATTAN KANAMA VAR MI? BOK DELİKLERİNİZİ KONTROL EDİN.",
["vld_ko1b_05_02"] = "KÖTÜ HİSSEDERSENİZ SÖYLEYİN. YA DA SAÇLARINIZ DÖKÜLÜRSE. YA DA TAŞAKLARINIZ DÜŞERSE.",
["vld_ko1b_05_03"] = "GÜVENLİ OLMALARI GEREK AMA... KÜÇÜK DİŞLER KEMİK İLİĞİNİZİ YİYORMUŞ GİBİ HİSSEDEN VAR MI?",
["vld_ko1b_05_04"] = "ÇOK GÜVENLİ OLDUKLARINA EMİNİM. AMA YİNE DE KALAN ÖMRÜNÜZÜN HER GÜNÜNÜN TADINI ÇIKARIN.",
