["vld_ko1b_05_07"] = "UMARIM HASTA OLMUYORSUNUZDUR. FENA BİR SOĞUK ALGINLIĞI DOLAŞIYOR. EVET, MUHTEMELEN SADECE ÜŞÜTMÜŞSÜNÜZDÜR.",
["vld_ko1b_05_08"] = "UMARIM RADYASYON SİZİ ETKİLEMİYORDUR. AMA İYİ TARAFINDAN BAKIN, BELKİ SÜPER GÜÇ KAZANIRSINIZ, DEĞİL Mİ?",
