["vld_ko1b_06_01"] = "ŞU GÜÇLÜ ARABAYI GÖRÜYOR MUSUNUZ? GADDAFİ'NİN ORİJİNAL 1965 LONGFELLOW'U. ARTIK SİZİN.",
["vld_ko1b_06_02"] = "BU GADDAFİ'NİN KLASİK 1965 LONGFELLOW'U MU? NÜKLEERLERİ BANA GETİRMEK İÇİN DAHA MÜKEMMEL YOL DÜŞÜNEBİLİYOR MUSUNUZ?",
["vld_ko1b_06_03"] = "AH, ŞURADA! BİR LONGFELLOW! 1965 MODEL, 4.7 LİTRE V8. HAVALI YOLCULUKLARI SEVERSİNİZ, DEĞİL Mİ?",
["vld_ko1b_07_01"] = "O GÜÇLÜ ARABAYI GÖRÜYOR MUSUNUZ? GADDAFİ'NİN ORİJİNAL 1965 MODELİ. ARTIK SİZİN ARACINIZ.",
["vld_ko1b_07_02"] = "BU GADDAFİ'NİN KLASİK 1965 GÜÇLÜ ARABASI MI? NÜKLEERLERİ BANA GETİRMEK İÇİN DAHA MÜKEMMEL YOL DÜŞÜNEBİLİYOR MUSUNUZ?",
["vld_ko1b_07_03"] = "AH, ŞURADA! 1965, 4,7 LİTRE V8. O YIL ÜRETİLEN EN İYİ İKİNCİ ŞEY, DEĞİL Mİ?",
["vld_ko1b_08_01"] = "GÜZEL! KALANINI ALIN, BURADAN ÇIKARALIM. UMARIM BU LANET TREN SARSINTISIZ GİDER.",
["vld_ko1b_08_02"] = "İLKİ TAMAM. AH, KÜÇÜCÜK BİR ŞEY AMA WASHINGTON'I HARİTADAN SİLMEYE YETER.",
["vld_ko1b_08_03"] = "İŞTE BU. AHHHHH, NEREDEYSE BAŞTAN ÇIKIYORUM. GÜN BATIMINDA İKİ GÜNEŞ GÖRMEK. BÜYÜLEYİCİ.",
["vld_ko1b_09_01"] = "ONLARA DİKKAT EDİN. WASHINGTON'I ERİMİŞ CAMA ÇEVİRESİM YOK. BUGÜN DEĞİL.",
["vld_ko1b_09_02"] = "GÜZEL, GÜZEL. GETİRMEYE DEVAM EDİN. KÜÇÜK BABUŞKALARIMA NAZİK DAVRANIN.",
["vld_ko1b_09_03"] = "HER BİRİ BİR KRAL FİDYESİ GETİRECEK. HEM DE GERÇEK ANLAMDA (GÜLER)!",
["vld_ko1b_cbf_01_01"] = "O MURKYWATER DEPOSUNA GİZLİCE GİREREK BAŞARDIĞINIZ HARİKA İŞİ DUYDUM. ÇOK ETKİLEYİCİ. ORAYA DÖNMENİZİ İSTİYORUM. O PARALI ASKERLER ‘UFAK BİR ŞEY’ SAKLAMIŞ. İSTEDİĞİM UFAK BİR ŞEY. MURKY'LER ÇEKİLİYOR. BİR TAVŞAN DELİĞİNDE KAYBOLMADAN ÖNCE ONU ALMAM GEREKİYOR.",
["vld_ko1b_cnc_01_01"] = "SEVGİLİ DOSTLARIM. HIZLI BİR TESLİM ALMA İŞİ. MURKYWATER DEPOSUNDAN BANA 'KÜÇÜK BİR ŞEY' GETİRİN.",
["vld_ko1b_cnc_01_02"] = "MURKYWATER DEPOSUNDAN BANA GETİRMENİZİ İSTEDİĞİM ‘UFAK BİR ŞEY’ VAR. ÇABUCAK DALIP KAPACAKSINIZ.",
["vld_ko1b_cnc_01_03"] = "NEHİR KENARINDAKİ MURKYWATER DEPOSUNDA BİR ŞEY VAR. İSTEDİĞİM BİR ŞEY.",
["vld_ko1b_end_01_01"] = "HARİKA İŞ, DOSTLARIM. YİNE BANA İYİ HİZMET ETTİNİZ. NÜKLEERLERİ DERT ETMEYİN. PARANIZIN TADINI ÇIKARIN.",
["vld_ko1b_end_01_02"] = "MUHTEŞEM! DOĞU KIYILARINI ATEŞE VERMEDEN KURTULDUĞUNUZA SEVİNDİM.",
["vld_ko1b_end_01_03"] = "AFERİN DOSTLARIM! O MURKY PİÇLERİNİN BUNU NASIL AÇIKLAYACAĞINI GÖRMEK İÇİN SABIRSIZLANIYORUM.",
["vld_mallcrashers_brf_outro_01"] = "BU SAVAŞ, SAVAŞTA DA BİZ KAZANIRIZ!",
["vld_mallcrashers_brf_outro_02"] = "BU SAVAŞ, SAVAŞTA DA BİZ KAZANIRIZ!",
["vld_mallcrashers_brf_speak_01"] = "BAY STONE APTAL. BENİ DİNLEMİYOR. BENDEN KORUYACAK YENİ KORUYUCUSU OLDUĞUNU SÖYLÜYOR. ADAMIN ARKASINDA DURUNCA PEK CESUR.",
["vld_mallcrashers_brf_speak_01b"] = "BÜYÜK HATA OLDUĞUNU GÖSTERECEKSİNİZ. BEN DE SONRA RAKİPLERİYLE İŞ YAPARIM. DİĞER ZAYIF KORUYUCULARA ÖRNEK OLUR. ALIŞVERİŞ MERKEZİNE GİDİP HER ŞEYİNİ VURUN. YANMALI.",
["vld_mallcrashers_brf_speak_02"] = "BAY STONE'UN ALIŞVERİŞ MERKEZİ. DEDİĞİNİZ GİBİ ÇÖKÜP YANMALI. GİDİP BÜTÜN DÜKKÂNLARI, CAMLARI, EŞYALARI YOK EDİN. İSTEDİĞİNİZİ ALIN AMA HASAR VERİN. BAY STONE CİDDİ OLDUĞUMU GÖRSÜN!",
["vld_mallcrashers_brf_speak_03"] = "GÜZEL İŞ DEĞİL AMA GÜÇ GÖSTERMEK İÇİN GEREKLİ. BAY STONE'UN ALIŞVERİŞ MERKEZİNİ SAVAŞ YOLUNDAKİ SOVYET RUS TANKLARI GİBİ YOK EDERİZ. BULDUĞUNUZ PARAYI ALIN, AYAKTA HİÇBİR ŞEY BIRAKMAYIN.",
["vld_mallcrashers_cnc_01"] = "GERİ DÖNDÜM DİYE O LANET İNATÇI (APTAL) HARACINI ÖDEMİYOR. FİKRİNİ DEĞİŞTİRİRİZ.",
["vld_mallcrashers_cnc_02"] = "ESKİ KORUMA İŞİM YENİDEN BAŞLAMALI. ELİMDEN ALDILAR, MÜŞTERİLERİN DE FİKİR DEĞİŞTİRMESİ GEREK.",
["vld_mallcrashers_cnc_03"] = "KORUMANIN İŞLEMESİ İÇİN YIKIM GEREKİR. ONLARIN YERİNİ YOK EDECEKSİNİZ, BEN DE NASIL DİYORSUNUZ, PAZARLAMAYI VE \"YENİ İŞ MODELİNİ\" HALLEDERİM.",
["vld_mallcrashers_debrief_01"] = "ALIŞVERİŞ MERKEZİ ARTIK YOK. HER YER DUMAN. SAVAŞINIZI BEĞENDİM. ARTIK İŞLER İYİ OLUR, VLAD KORKUSU BÜYÜDÜ. SAĞ OLUN.",
["vld_mallcrashers_debrief_02"] = "AH, HAHA. BU, NASIL DİYORSUNUZ: AŞIRIYA KAÇMAKTI. BAYILDIM! HAPİSTE YILLARCA BUNU HAYAL ETTİM! PARA SİZİN, HAK ETTİNİZ DOSTLARIM.",
["vld_mallcrashers_debrief_03"] = "HEY! RUS METRES GİBİ ALIŞVERİŞ YAPIYORSUNUZ, VU! ŞAK, ŞAK, ŞAK! HIZLISINIZ, HASAR DA VERİYORSUNUZ, HA!? İYİ PARA, İYİ İÇKİ SİZİN OLSUN DOSTLARIM. BEN, VLAD, KORUMA İŞİNE YİNE SAHİP OLDUM! HEHEHE!",
["vld_mallcrashers_debrief_04"] = "AVM ZİYARETİNİZ İŞE YARADI. ATEŞ VE CAM, VLAD'IN KULAĞINA MÜZİK GİBİ! YİNE KORUMA YAPIYORUM, PARA DA... PARA İYİ OLACAK. BANA İYİLİK YAPTINIZ. SPASİBA.",
["vld_moon_01_01"] = "DOSTLARIM, NOEL'İMİ KURTARACAKSINIZ.",
["vld_moon_01_02"] = "BU İŞİ BENİM İÇİN ÇÖZERSENİZ SİZE GÜZEL NOEL HEDİYELERİ ALIRIM.",
["vld_moon_01_03"] = "GİDİN NOEL BABA'YI BULUN KÜÇÜK YARDIMCILARIM. HÂLÂ BEMBEYAZ BİR NOEL GEÇİREBİLİRİZ.",
["vld_moon_02_01"] = "SARHOŞ NOEL BABA, LANET BİR REZALET! BİR DE KOKAİNİM!",
["vld_moon_02_02"] = "BU KOKAİNİ KAYBEDERSEM NOEL BÜTÇEM SİKİLİR. BENİM İÇİN BULUN!",
["vld_moon_02_03"] = "POLİS NOEL BABA'YI NASIL TUTUKLAR? DOĞRU DEĞİL!",
["vld_moon_03_01"] = "LÜTFEN KAYINBİRADERİMİ KURTARIN. APTAL AMA AİLEDEN.",
["vld_moon_03_02"] = "UMARIM KAYINBİRADERİM KOKAİNİ NEREYE KOYDUĞUNU HATIRLAR.",
["vld_moon_03_03"] = "BU ALIŞVERİŞ MERKEZİNDE POLİSLERİN KORUDUĞU KAFASI KIYAK TEK BİR NOEL BABA OLABİLİR. UMARIM.",
["vld_moon_04_01"] = "UYUYOR MU LAN? UYANDIRIN ONU!",
["vld_moon_04_02"] = "ŞU PİSLİĞE BİR TANE ÇAKIN DA UYANSIN!",
["vld_moon_04_03"] = "EMİNİM O YARGILAYICI PİÇ NOEL BABA'YI HEP YUMRUKLAMAK İSTEMİŞSİNİZDİR! İŞTE FIRSATINIZ!",
["vld_moon_04_04"] = "O APTALA BENDEN BİR TANE PATLATIN!",
["vld_moon_04_05"] = "SAĞLAM BİR YUMRUK ATIN! AYILTIN, DERSİNİ VERİN!",
["vld_moon_04_06"] = "ÇEKİNMEYİN! İYİCE PATAKLAYIN ONU!",
["vld_moon_05_01"] = "KUYUMCU! EN SEVDİĞİM YER!",
["vld_moon_05_02"] = "ELMASLAR SONSUZA DEK KALIR AMA İYİ KOKAİN ÇABUK KAYBOLUR. GİDİP ALIN!",
["vld_moon_05_03"] = "TAŞLAR VE KOKAİN. GÜZEL!",
["vld_moon_09_01"] = "HADİ, HACKER OLABİLDİĞİNİZİ GÖSTERİN!",
["vld_moon_09_02"] = "TUŞ TAKIMLARI, ELEKTRONİK SİHİR. AH, YAPARSINIZ SİZ!",
["vld_moon_09_03"] = "VİTRİN KİLİTLİ! BU PİSLİKLERİN HAZİNELERİNİ NASIL SIKI KORUDUĞUNA BAKIN! MASALLARDAKİ EJDERHA GİBİ!",
["vld_moon_10_01"] = "MÜKEMMEL! ŞİMDİ MÜCEVHER KUTUSUNU ALIN!",
["vld_moon_10_02"] = "BENİM İÇİN BİRAZ DEĞERLİ TAŞ ALIN!",
["vld_moon_10_03"] = "İŞTE BÖYLE! ŞİMDİ KOKAİNLİ MÜCEVHERLERİ ALIN!",
["vld_moon_13_01"] = "NE OLUYOR LAN. OYUNCAKLARIN İÇİNDE KOKAİN Mİ? HARİKA! BUNU HATIRLAMALIYIM.",
["vld_moon_13_02"] = "APTAL PİÇ KOKAİNİ OYUNCAK KUTUSUNA SAKLAMIŞ!",
["vld_moon_13_03"] = "KÜÇÜK ÇOCUĞUN BİRİ ÇALIP PARA KAYBETMEDEN O KOKAİNİ ALIN!",
["vld_moon_14_01"] = "NE! ALIŞVERİŞÇİ BİR PİSLİK KOKAİNİMLE DOLAŞIYOR! BULUN!",
["vld_moon_14_02"] = "NE? HAYIR! BÜTÜN TİN BOY'LARI SATMIŞLAR!",
["vld_moon_14_03"] = "TÜKENDİ Mİ? SİKTİR, BİRİ BİR LİBRE KOKAİNİ HARİKA FİYATA ALMIŞ.",
["vld_moon_15_01"] = "HEY TENEKE OĞLAN! UYUŞTURUCU SORUNUN VAR!",
["vld_moon_15_02"] = "TİN BOY KOKAİNİ ÇEKMİŞ!",
["vld_moon_15_03"] = "TİN BOY'UN KAR BEYAZI RUHU VAR! HAHAHA!",
["vld_moon_16_01"] = "DİĞER OYUNCAKLARI SİKTİR EDİN, TİN BOY'U ALIN!",
["vld_moon_16_02"] = "KOKAİNİMİN OLDUĞU TİN BOY'U ALIN!",
["vld_moon_16_03"] = "TİN BOY, NEREDESİİİN?",
["vld_moon_17_01"] = "10 MU? BENİM BEDENİM! AYAKKABIDAN DA BAHSETMİYORUM...",
["vld_moon_17_02"] = "O LANET AYAKKABILARI ALIN!",
["vld_moon_17_03"] = "NE APTAL! AYAKKABILARI BULUN!",
["vld_moon_18_01"] = "SİKTİĞİMİN AYAKKABI KUTUSUNU BULMAK NE KADAR ZOR OLABİLİR?",
["vld_moon_18_02"] = "ESKİ SOVYET AYAKKABILARINI ÖZLÜYORUM. SEÇMEK İÇİN BU KADAR APTAL MODEL YOKTU!",
["vld_moon_18_03"] = "HADİ, BİLGİSAYARLA HESAP YAPIN!",
["vld_moon_19_01"] = "TAMAM, DEPODA OLMALI. LANET KAPIYI MATKAPLA DELİN.",
["vld_moon_19_02"] = "O KAPIYI MATKAPLA AÇIN, AYAKKABILARI BULUN, KOKAİNİMİ ALIN!",
["vld_moon_19_03"] = "KAPIYI MATKAPLA AÇIP KOKAİN DOLU AYAKKABI KUTUMU ALIN!",
["vld_moon_20_01"] = "O LANET AYAKKABILARI ALIN!",
["vld_moon_20_02"] = "KOKAİNİMİN OLDUĞU AYAKKABILARI ALIN!",
["vld_moon_20_03"] = "KOKAİNİMİ ALIN!",
["vld_moon_21_01"] = "BURADA ÇOK FAZLA LANET KUTU VAR!",
["vld_moon_21_02"] = "NEREDE. O. AYAKKABILAR? NEREDE?!",
["vld_moon_21_03"] = "NEREDELER PEKİ?!",
["vld_moon_22_01"] = "BURANIN BU KADAR DAĞINIK OLDUĞUNA İNANAMIYORUM.",
["vld_moon_22_02"] = "BU KUTULARDA NE VAR?",
["vld_moon_22_03"] = "HER YERDE LANET KUTULAR. ŞU VİDEO OYUNU GİBİ...",
["vld_moon_23_01"] = "VR MI? O NE SİKİM?",
["vld_moon_23_02"] = "VR. VERY... YANİ ÇOK... GELİŞTİRİLMİŞ... GERÇEKLİK. NE SAÇMALIK.",
["vld_moon_23_03"] = "KOKAİN VE SANAL GERÇEKLİK; NE İLGİNÇ BİR KARIŞIM.",
["vld_moon_24_01"] = "O LANET VR SETİNİ NEREYE SAKLAMIŞLAR? ALTERNATİF GERÇEKLİĞE Mİ?",
["vld_moon_24_02"] = "SANAL GERÇEKLİK SETİ SANAL OLARAK BURADA YOK. YOKSA GERÇEK OLARAK MI DEMELİYİM? BİLMİYORUM, HANGİSİ?",
["vld_moon_24_03"] = "VR: VLAD RESMEN COŞUYOR. BENİM İÇİN ANLAMI BU.",
["vld_moon_25_01"] = "AH, BİR KASA! NE İLGİNÇ!",
["vld_moon_25_02"] = "MİNİCİK BİR KASANIN SİZİN İÇİN SORUN OLMADIĞINA EMİNİM.",
["vld_moon_25_03"] = "BEN DE KASA'YA SAKLARDIM. AMA BEN KUŞKUCU BİR ADAMIM.",
["vld_moon_26_01"] = "NOEL HEDİYELERİNİ AÇMAYA BAYILIRIM!",
["vld_moon_26_02"] = "HADİ, NE BEKLİYORSUNUZ?",
["vld_moon_26_03"] = "MALLARI ALIN, DOSTLARIM!",
["vld_moon_27_01"] = "BORŞ ÇORBAMIN YANINDA İYİ ŞARABA BAYILIRIM! LEZZETLİ!",
["vld_moon_27_02"] = "ŞARABI ALIN! AMA İÇMEYE BAŞLAMAYIN, BİR SARHOŞ NOEL BABA YETER!",
["vld_moon_27_03"] = "ŞARAP VE KOKAİN! PARTİ PAKETİ OLARAK SATABİLİRİZ!",
["vld_moon_28_01"] = "O RED RED RESURRECTİON'I YA DA ADI HER NEYSE ONU ALIN!",
["vld_moon_28_02"] = "BELKİ ŞARAP İTHALATINA DA BAŞLAMALIYIM! VLAD'İN ŞARAPLARI! KULAĞA HOŞ GELİYOR.",
["vld_moon_28_03"] = "ŞARAP, KADINLAR VE ŞARKILAR! BİR DE KOKAİN! MUTLU NOELLER!",
["vld_moon_29_01"] = "DOSTUMUZ BILE YAKINDA PARTİ SONRASINA GELECEK. ONU KARŞILADIĞINIZDAN EMİN OLUN.",
["vld_moon_29_02"] = "HELİKOPTERİ KOLLAYIN. BU MALLARI GÖĞE ÇIKARIYORUZ.",
["vld_moon_29_03"] = "YUKARIDAN KURTULUŞ YAKINDA GELİYOR, DOSTLARIM!",
["vld_moon_30_01"] = "ŞİMDİ AĞACI BU GÜZEL ŞEYLERLE SÜSLEYİN!",
["vld_moon_30_02"] = "AĞACA KARLA HAYAT VERİN!",
["vld_moon_30_03"] = "İÇİNDE HEDİYELER OLAN GÜZEL BİR NOEL AĞACI İSTİYORUM!",
["vld_moon_31_01"] = "DİNLEYİN DOSTLARIM... DÜŞÜNDÜM DE... O ÇOK GÜZEL BİR NOEL AĞACI. SANIRIM ALACAĞIM. ALMASI İÇİN HELİKOPTERİ GÖNDERECEĞİM.",
["vld_moon_31_02"] = "AĞACI İSTİYORUM. KOCAMAN BİR NOEL ROKETİ GİBİ GÖĞE UÇACAK! HAHAHA!",
["vld_moon_31_03"] = "O AĞAÇ ÇOK GÜZEL. ÇALACAĞIZ.",
["vld_moon_32_01"] = "BAYANLAR BAYLAR, BİRAZ PATLAYICI YERLEŞTİRİR MİSİNİZ LÜTFEN?",
["vld_moon_32_02"] = "DİNLEYİN... BANA BÜYÜK BİR PATLAMA YAPMANIZ GEREK.",
["vld_moon_32_03"] = "BU ALIŞVERİŞ MERKEZİNİN TAVANINI UÇURMAK GÜZEL OLUR BENCE!",
["vld_moon_33_01"] = "TAMAM, BU KÜÇÜK BEBEĞİ KALDIRIP ÇIKARMAMIZ GEREKİYOR.",
["vld_moon_33_02"] = "BU AĞAÇ UÇACAK DOSTLARIM!",
["vld_moon_33_03"] = "GÜZEL BİR AĞAÇ, ALACAĞIZ. ZARAR VERMEYİN!",
["vld_moon_34_01"] = "BU AĞAÇ GİDİYOR. NOEL BABA DA ÖYLE!",
