["vld_pt1_intro_01"] = "TAMAM, ARTIK... DÜRÜST OLMA VAKTİ. KOKAİN... KEÇİLERE DOLDURULDU. EVET, KEÇİLERE. BİR DE KAÇMIŞLAR. HAHA, KURNAZ KEÇİLER, HA?! BULUN ONLARI!",
