["vld_pt2_03_01"] = "DURUN, KEÇİLERİN HEPSİNİ ALMADINIZ. GÖT DELİĞİM OYUNCAĞINIZ MI SİZİN? KEÇİLERİN HEPSİNİ İSTİYORUM. ",
