["vld_pt2_04_03"] = "YILA BAŞLAMAK İÇİN HARİKA YOL. ELDEN ÇIKARILACAK BİR DAĞ KOKAİNLE! TEBRİKLER, SEVGİLİ DOSTLAR.",
