["vld_quote_set_a_06"] = "BEN VOTKAYI SEVMİYORUM AMA O BENİ PEK SEVİYOR.",
["vld_ukranian_brf_intro_01"] = "DOSTLAR...",
["vld_ukranian_brf_intro_02"] = "MERHABA DOSTLARIM, KÜÇÜK BİR İYİLİK İSTEYECEĞİM...",
["vld_ukranian_brf_outro_01"] = "BOL ŞANS, DOSTLARIM. VLAD SİZİ TAKDİR EDİYOR.",
["vld_ukranian_brf_outro_02"] = "BOL ŞANS, DOSTLARIM. VLAD SİZİ TAKDİR EDİYOR.",
["vld_ukranian_brf_speak_01"] = "BANA TUZAK KURAN ANASIZ OROSPU ÇOCUĞU DMİTRİ EVLENİYOR. GELİNİ DÜĞÜNE HAZIRLANIYOR. AH! BÜYÜK MÜKEMMELİYETÇİ! HOH!",
["vld_ukranian_brf_speak_01c"] = "GİDİN. TACI ÇALIN. İÇERİDEKİ HER ŞEYİ ÇALIN. SİKİMDE DEĞİL! AMA TACI ALIN, ANLADINIZ MI? ALDIĞINIZ DİĞER HER ŞEY SİZİN; BEN SADECE O MÜKEMMEL SİKİK GÜNLERİNİ MAHVETMEK İSTİYORUM!",
["vld_ukranian_brf_speak_02"] = "DMİTRİ İLE OROSPU GELİN EVLENİYOR. ÇİÇEK GÖNDERMEK YERİNE O KUSURSUZ PRENSESE DAHA İYİ BİR DÜĞÜN HEDİYEM VAR: SİKTİĞİMİN TACINI ÇALIN...",
["vld_ukranian_brf_speak_02c"] = "TAÇ ŞEHİR MERKEZİNDEKİ KUYUMCUDA. ETRAFI ARAYIN... MUHTEMELEN KASADA AMA BELKİ DEĞİL. ÇALIŞMAYI SEVİYORSUNUZ, DEĞİL Mİ? TACI ALIP BENİ MUTLU EDİN. ONLARI DA... MUTSUZ.",
["vld_ukranian_brf_speak_03"] = "BASİT. EVLİLİĞİN YANLIŞ BAŞLAMASINI İSTİYORUM. BENİ KAZIKLAYAN DMİTRİ EVLENİYOR. DOĞAL OLARAK BU GÜN ONUN İÇİN MUTLU OLAMAZ.",
["vld_ukranian_brf_speak_03c"] = "TAÇ ŞEHİR MERKEZİNDEKİ DÜKKÂNDA. DÜKKÂNIN NERESİNDE OLDUĞUNU BULUN. BELKİ KASADA, BELKİ DEĞİL... ARAMAK EĞLENCENİN YARISI, DEĞİL Mİ? BANA TACI GETİRİN YETER. DİĞER HER ŞEY SİZİN.",
["vld_ukranian_cnc_01"] = "DOSTLARIM, KÜÇÜK BİR SORUNDA YARDIM EDER MİSİNİZ? BİR... AİLE SORUNU ÇIKARMANIZ GEREK.",
["vld_ukranian_cnc_02"] = "İYİ DOSTLARIM, VLAD'İN AİLE MESELESİNDE BİRAZ YARDIMA İHTİYACI VAR. ANLARSINIZ, UFAK SOYGUN.",
["vld_ukranian_cnc_03"] = "DOSTLARIM, VLAD'İN DÜĞÜN PLANLAMASINDA UFAK YARDIMA İHTİYACI VAR.",
["vld_ukranian_cnc_04"] = "DOSTLARIM, VLAD'İN DÜĞÜN İÇİN MÜCEVHER SEÇERKEN YARDIMA İHTİYACI VAR... SAKINCASI YOKSA.",
["vld_ukranian_debrief_01"] = "AH, SEVİNÇTEN UÇUYORUM. HEHEHEY! HARİKA BİR İYİLİK YAPTINIZ. O PRENSES TENEKE TAKMAK ZORUNDA KALDI. HAH! HAHAHA! VLADİMİR VLADİMİROVİCH SİZE BORÇLU!",
["vld_ukranian_debrief_02"] = "PARAYI HAK ETTİNİZ. GELİNİ O KADAR KIZDI Kİ DÜĞÜNÜ ERTELEDİ. AH ZAVALLI, ZAVALLI DMİTRİ. ONUN İÇİN ÇOK TUZLU GÖZYAŞI DÖKÜYORUM.",
["vld_ukranian_debrief_03"] = "SİZ! HARİKA İNSANLARSINIZ! HARİKA İŞ YAPIYORSUNUZ! DMİTRİ ŞİMDİ YENİ BİR TAÇ BULMAK ZORUNDA! HAH. BEN Mİ? BUNU ÇERÇEVELETECEĞİM. AH... NE MUTLU ANILAR... TEŞEKKÜRLER.",
["vld_ukranian_debrief_04"] = "HARİKA, HARİKA. KARISINI ÖLDÜREBİLİRDİM TABİİ... AMA KARISININ BİR SÜRE ÖLÜ OLMASI YERİNE, ÖMÜR BOYU ONUN BAŞININ ETİNİ YEMESİ DAHA İYİ BENCE.",
["vr_belt_grip"] = "SEÇMEK İÇİN KAVRA",
["vr_reloading"] = "ŞARJÖR DEĞİŞTİRİLİYOR",
["wild_desc"] = "UYRUĞU: AMERİKALI$NL;YAŞI: 61$NL;$NL;OVERKİLL MC OPERASYONLARINI BOZMAK İÇİN İÇERİDE BİR ADAMA İHTİYACIM VARDI. O ADAM TOM \"RUST\" BİSHOP’TI. ELEPHANT’IN YARDIMIYLA RUST’A GERÇEKTEN BÜYÜK BİR VURGUN YAPMA FIRSATI SUNDUK; RUST DA HİÇ VAKİT KAYBETMEDEN KABUL ETTİ. BANA OLAN YENİ SADAKATİNİ KANITLAMAK İÇİN ESKİ MOTOSİKLETÇİ KARDEŞLERİNİ ÖLDÜRDÜ VE ANLAŞMA KESİNLEŞTİ. RUST ARTIK BİZİM TARAFTA OLDUĞUNA GÖRE SIRADAKİ PLANIMA GEÇEBİLİRİZ.",
["wlf_pal_intro_01"] = "BODHI'NİN HAVUZ TAMİR SERVİSİ.",
["wlf_pal_intro_02"] = "DUYDUĞUMA ÜZÜLDÜM EFENDİM! ADAMLARIMIZI HEMEN GÖNDERECEĞİZ!",
["wp_uc_power_back_up"] = "ELEKTRİĞİ GERİ GETİR!",
["wp_uc_saw_limo"] = "LİMUZİNİ AÇMAK İÇİN TESTEREYİ KULLAN!",
["xuk_chca_08_01"] = "SİZİ TANIYORUM! BİZİMLE KAÇ KEZ YOLCULUK ETTİNİZ ARTIK?",
["xuk_chca_08_02"] = "SİZİN VE PARANIZIN BURADA HER ZAMAN YERİ VAR.",
["xuk_chca_08_03"] = "AH, BURADA ÇOK TANIDIK YÜZ VAR, DAHA FAZLA EĞLENCE İÇİN DÖNMÜŞLER!",
["xuk_chca_08_04"] = "DENİZDE KUMAR OYNAMAK, HAYATIN EN GÜZEL ŞEYLERİNDEN BİRİ DEĞİL Mİ?",
["xuk_chca_08_05"] = " BAY WANG SAYESİNDE HEPİNİZİ KEYİFLİ BİR YOLCULUK BEKLİYOR.",
["xuk_chca_09_01"] = "YENİ AVİZEMİZİ HERKES GÖRDÜ MÜ? BİR ANTİKA. HONG KONG'DAN ÖZEL OLARAK GETİRTTİM.",
["xuk_chca_09_02"] = "SİZ BATILILAR PEK ÇOK ŞEYİ YANLIŞ BİLİYORSUNUZ. KARA KEDİ UĞURSUZLUK DEĞİL, UĞUR GETİRİR!",
["xuk_chca_10_01"] = "BİRİNİ BULUN DA ŞU PİSLİĞİ TEMİZLESİN. ",
["xuk_chca_10_02"] = "BUGÜN GÜZEL PARA GELİYOR.",
["xuk_chca_10_03"] = "WAN CHENG'İ GÖREN VAR MI?",
["xuk_chca_10_04"] = "Lİ DENG DENEN O APTAL NEREDE?",
["xuk_chca_10_05"] = "Lİ DENG BENİ ARAMAYA GELİRSE RAHATSIZ EDİLMEK İSTEMEDİĞİMİ SÖYLEYİN!",
["xuk_chca_10_06"] = "KRUPİYELERİN YER DEĞİŞTİRME VAKTİ GELDİ. ",
["xuk_chca_10_07"] = "GEÇEN HAFTA YAKALADIĞIMIZ KART SAYICIYA NE OLDUĞUNU DUYDUN MU? O KADAR UTANMIŞ Kİ KENDİNİ DENİZE ATMIŞ... ANA KARAYA YÜZMEYE ÇALIŞMIŞ!",
["xuk_chca_11_01"] = "HONG KONG'DAN HİÇ AYRILMAMALIYDIM.",
["xuk_chca_11_02"] = "BU ZAVALLI İNSANLAR NİYE BANA SÜREKLİ BİR ŞEY SORUYOR?",
["xuk_chca_11_03"] = "LANET GARSONA MI BENZİYORUM?",
["xuk_chca_11_04"] = "EVET... KÜÇÜK PAPAĞANLAR GİBİ KUMAR OYNAYIN.",
["xuk_chca_12_01"] = "HEY! NELER OLUYOR?",
["xuk_chca_12_02"] = "BİRİNİ BURAYA GÖNDERİN DE ŞUNU TAMİR ETSİN!",
["xuk_chca_12_03"] = "PAYDAY GANG! VURUN ŞUNLARI!",
["xuk_chca_12_04"] = "DAHA FAZLA MUHAFIZ ÇAĞIRIN!",
["xuk_chca_12_05"] = "BU GEMİDEN SAĞ ÇIKAMAYACAKSINIZ PALYAÇOLAR!",
["xuk_chca_13_01"] = "PAYDAY GANG! BURADALAR!",
["xuk_chca_13_02"] = "O PALYAÇOLAR BURADA! BEN İLGİLENECEĞİM!",
["xuk_chca_call_01_01"] = "ALO, KİMİNLE GÖRÜŞÜYORUM?",
["xuk_chca_call_01_02"] = "EVET, NE VAR?",
["xuk_chca_call_01_03"] = "EVET?",
["xuk_chca_call_01_04"] = "XUN KANG. KONUŞ.",
["xuk_chca_call_01_05"] = "KONUŞ. DİNLİYORUM.",
["xuk_chca_call_02_01"] = "BAY... LOCKE? NUMARAMI BULMANIZA ŞAŞIRDIM.",
["xuk_chca_call_02_02"] = "TEKRAR MERHABA BAY KOZAK. NASIL HİSSEDİYORSUNUZ?",
["xuk_chca_call_02_03"] = "EH, NE ZAMAN ARAYACAĞINI MERAK EDİYORDUM.",
["xuk_chca_call_03_01"] = "HATIRLADIĞIM KADARIYLA HAYIR, NEDEN?",
["xuk_chca_call_03_02"] = "KORKARIM ANLAYAMADIM.",
["xuk_chca_call_03_03"] = "ÇOCUK MASALLARIYLA İLGİLENMİYORUM.",
["xuk_chca_call_03_04"] = "HAYIR AMA EJDERHA KAZANIR DİYE TAHMİN EDERİM.",
["xuk_chca_call_04_01"] = "ZALİM ÇOCUK, ÖYLE GÜZEL BİR YARATIĞI ÖLDÜRMEK DE NE. ",
["xuk_chca_call_04_02"] = "ÖYLE Mİ? ÇOCUKLAR ACIMASIZDIR.",
["xuk_chca_call_04_03"] = "BİR DÜŞÜN, ÇOCUKLARIN ACIMASIZLIĞI.",
["xuk_chca_call_04_04"] = "EJDERHA NEDEN HİÇ KAZANMAZ?",
["xuk_chca_call_04_05"] = "YAZIK AMA EJDERHA BU KADAR APTALSA ÖLMEYİ HAK ETMİŞTİR.",
["xuk_chca_call_05_01"] = "GERÇEKTEN Mİ? BU ÇOK İLGİNÇ OLACAK.",
["xuk_chca_call_05_02"] = "DÖRT GÖZLE BEKLİYORUM.",
["xuk_chca_call_05_03"] = "BENİ BULABİLİRSENİZ DENEMEKTE SERBESTSİNİZ.",
["xuk_chca_call_05_04"] = "SANKİ DAHA ÖNCE HİÇ TEHDİT EDİLMEDİĞİMİ SANIYORSUNUZ.",
["xuk_chca_meeting_01_01"] = "SORUNSUZ İLERLİYOR. BU AKŞAM KAZANCIMIZ İYİ OLUR.",
["xuk_chca_meeting_01_02"] = "ULUSLARARASI SULARA GİRDİK. BU YOLCULUK KÂRLI OLACAK.",
["xuk_chca_meeting_01_03"] = "HER ŞEY KONTROL ALTINDA. BU YOLCULUKTAN İYİ KAZANÇ SAĞLAYACAĞIZ.",
["xuk_chca_meeting_02_01"] = "GÜVENLİĞİ ARTIRMAK GEREKSİZ DİKKAT ÇEKEBİLİR. BİZİ DE ZAYIF GÖSTERİR.",
["xuk_chca_meeting_02_02"] = "BU BİZİ ZAYIF GÖSTERİR.",
["xuk_chca_meeting_02_03"] = "SORUN OLMAYACAK. ",
["xuk_chca_meeting_02_04"] = "ENDİŞELİ DEĞİLİM.",
["xuk_chca_meeting_02_05"] = "HALLETTİM.",
["xuk_chca_meeting_03_01"] = "O SENİN SORUMLULUĞUNDAYDI!",
["xuk_chca_meeting_03_02"] = "SUÇU BANA ATMA!",
["xuk_chca_meeting_03_03"] = "SENİN HATANDI ÇOCUK!",
["xuk_chca_meeting_03_04"] = "BUNU BANA YIKMA, ŞIMARIK KIZ!",
["xuk_chca_meeting_04_01"] = "BENCE ENDİŞELENMEYE GEREK YOK. BURADA BİR ŞEYE KALKIŞACAK KİŞİNİN AKLINI KAÇIRMIŞ OLMASI GEREKİR.",
["xuk_chca_meeting_04_02"] = "ENDİŞELENMEYE GEREK OLDUĞUNU SANMIYORUM. BURADA BİR ŞEY DENEMEK APTALLIK OLUR.",
["xuk_chca_meeting_04_03"] = "ENDİŞELENMENİZE GEREK YOK.",
["xuk_chca_meeting_04_04"] = "ANLIYORUM MOUNTAIN MASTER. HER ZAMANKİ GİBİ BANA GÜVENEBİLİRSİNİZ.",
["xuk_chca_meeting_04_05"] = "HER ZAMANKİ GİBİ BANA GÜVENEBİLİRSİNİZ MOUNTAIN MASTER.",
["xuk_chca_meeting_05_01"] = "DIŞARIDA BÖLGEYİ DENETLİYOR.",
["xuk_chca_meeting_05_02"] = "O ZAVALLI APTAL KONTROLÜMDE.",
["xuk_chca_meeting_05_03"] = "SORUN ÇIKARAMAYACAĞI YERDE.",
["xuk_chca_meeting_05_04"] = "MASAJ YAPTIRIYOR. ORADA SORUN ÇIKARAMAZ.",
["xuk_chca_meeting_05_05"] = "HER ZAMANKİ GİBİ HAYALLERE DALMIŞ. AMA KONTROLÜMDE.",
["xuk_chca_meeting_06_01"] = "EMREDERSİNİZ, DAİ-LO.",
["xuk_chca_meeting_06_02"] = "YAPILACAK, DAİ-LO.",
["xuk_chca_meeting_06_03"] = "HER ZAMANKİ GİBİ, MOUNTAIN MASTER.",
["xuk_chca_meeting_06_04"] = "HER ZAMANKİ GİBİ BANA GÜVENEBİLİRSİNİZ.",
["xuk_chca_meeting_07_01"] = "GÜZEL, TEŞEKKÜRLER.",
["xuk_chca_meeting_07_02"] = "EPEY UZUN SÜRDÜ.",
["xuk_chca_meeting_07_03"] = "ONLAR BANA DAHA ÖNCE LAZIMDI!",
["xuk_chca_meeting_07_04"] = "GÜZEL, BUNLARA İHTİYACIM VARDI.",
["yuw_chca_01_01"] = "NELER OLUYOR? XUN KANG?!",
["yuw_chca_02_01"] = "SİZİ... SİKİKLER! OKYANUSUN DİBİNE KONTEYNER İÇİNDE BIRAKACAĞIM!",
["yuw_pent_threat_01"] = "SİZİ DAVET ETTİĞİMİ HATIRLAMIYORUM AMA FARK ETTİĞİNİZ GİBİ MİSAFİRLERİM İÇİN HER ZAMAN BİR KARŞILAMA EKİBİ HAZIR TUTARIM. BUYURUN, YUKARI GELİN. YALNIZ KALMAMANIZI SAĞLAYACAĞIM.",
["yuw_pent_threat_02"] = "AZMİNİZ TAKDİRE DEĞER AMA KİMİN SÖZ SAHİBİ OLDUĞUNU ANLAMIYORSUNUZ GİBİ. ÇABALARINIZIN ETKİLEYİCİ OLDUĞUNU KABUL EDEBİLİRİM AMA HATANIZ BURAYA GELMEKTİ.\nCAM DAĞIMIN ZİRVESİNE TIRMANIP BENDEN ÇALABİLECEĞİNİZİ Mİ SANDINIZ?\nŞUNU BİLİN: HAKKIM OLANI PENÇELERİMLE, DİŞLERİMLE VE ATEŞLE SAVUNACAĞIM.\n",
["yuw_pent_threat_03"] = "NE EĞLENCELİ, GERÇEKTEN VAZGEÇMİYORSUNUZ. ARKANIZDA MALLARIMIN EPEY KISMINI DA MAHVEDİYORSUNUZ. FARK ETMEZ, YENİDEN YAPABİLİRİM AMA SİZ ÖLÜMDEN DÖNEMEZSİNİZ.\nSANIRIM RAHATLAYIP BANA GELİRKEN TÖKEZLEMENİZİN TADINI ÇIKARACAĞIM. ADAMLARIM ÖLÜMÜNÜZE YÜRÜMEDEN ÖNCE SİZİ İYİCE YUMUŞATIR.",
["yuw_pent_threat_04"] = "AH, ŞİMDİ ANLADIM. BİRİ KULAĞINIZA BİR ŞEYLER FISILDAMIŞ. SİZİNLE İŞİM BİTİNCE BİR EV TEMİZLİĞİ YAPACAĞIM. HAİN SIÇANLAR, HAŞERELER. HAYIR HAYIR, BENİM EVİMDE OLMAZ.\n \nDAĞIN ETEĞİNDE DİZ ÇÖKÜP SİZİ AFFETMEM İÇİN YALVARMALIYDINIZ. AMA ONUN YERİNE ŞEREFSİZ KÖPEKLERİN SAFINI TUTTUNUZ. BEN DE SİZİ ÖYLE ÖLDÜRECEĞİM, KUDUZ HAYVANLAR GİBİ.\n",
["yuw_pent_threat_05"] = "HİSSEDİYOR MUSUNUZ? ONA ÇEKİLİYORSUNUZ VE ALEVLE BOĞUŞAN BİR GÜVE GİBİ YANIP ÖLECEKSİNİZ.\nSIRADAKİ ŞEY KADERDİR, KAÇINILMAZ. KABULLENİN.",
["yuw_sand_01_01a"] = "BENİM ADIM YUFU WANG. BENİ TANIMIYORSUNUZ.",
["yuw_sand_01_01b"] = "HEPİMİZİ BÜYÜK BİR ZAHMETTEN KURTARMAK ADINA, ALDIKLARINIZI GERİ VERMENİZ VE ÖRGÜTÜME TAZMİNAT ÖDEMENİZ İÇİN SİZE BİR FIRSAT VERECEĞİM.",
["yuw_sand_01_01c"] = "TEK FIRSAT. BAŞKASI YOK.",
["yuw_sand_01_02a"] = "DEMEK ADAMINIZI GERİ ALDINIZ. FARK ETMEZ, MESAJIMI VERDİM.",
["yuw_sand_01_02b"] = "BENDEN ALDIKLARINIZI GERİ VERECEK, SONRA İÇTEN BİR ÖZÜR MESAJI GÖNDERECEKSİNİZ. BELKİ O ZAMAN İŞİMİZ BİTER.",
["zep_ca1_01_01"] = "DOSTUM, BU ŞEY ANNENDEN YAVAŞ DÖNÜYOR.",
["zep_ca1_01_02"] = "EN SON BU KADAR BÜYÜK VE HANTAL BİR ŞEYİ TUTTUĞUMDA... NEYSE BOŞ VERİN.",
["zep_ca1_01_03"] = "BİRAZ YAN RÜZGÂR VAR. BAŞ EDEMEYECEĞİM BİR ŞEY DEĞİL.",
["zep_ca1_01_04"] = "ŞEHİR YUKARIDAN GÜZEL GÖRÜNÜYOR.",
["zep_ca1_01_05"] = "MİLLET, İÇERİDE ALTI JAPON TURİST KORKUDAN ALTINA SIÇIYOR. UMARIM İYİ FOTOĞRAF ÇEKERLER.",
["zep_ca1_01_06"] = "VUHUUU! AFGANİSTAN'DA B1 UÇURDUM. BU SİKİKLERDEN BİRİNİ SÜRECEĞİM AKLIMA GELMEZDİ.",
["zep_ca1_01_07"] = "ÇOOOOK SESSİZ BE...",
["zep_ca1_02_01"] = "YAKINDA ORADAYIM! DEVAM EDİN.",
["zep_ca1_02_02"] = "YOLDAYIM, DOSTLAR!",
["zep_ca1_02_03"] = "GELİYORUM. YAKLAŞIYORUM...",
["zep_ca1_02_04"] = "NEREDEYSE GELDİM MİLLET. COŞACAĞIZ!",
["zep_ca1_02_05"] = "LANET OLSUN, BU MATKAP KOCAMANMIŞ!",
["zep_ca1_03_01"] = "TEŞEKKÜRLER. HAVAİ FİŞEKLERİ GÖRÜYORUM. YOLDAYIZ!",
["zep_ca1_03_02"] = "TAMAM, HAVAİ FİŞEKLERİ GÖRDÜM. SİZE DÖNÜYORUM.",
["zep_ca1_03_03"] = "İŞARETİNİZİ GÖRÜYORUM. ROCK'N'ROLL! GELİYORUZ.",
["zep_ca1_03_04"] = "GÜZEL HAVAİ FİŞEKLER. GELİYORUZ.",
["zep_ca1_03_05"] = "GÖKYÜZÜNÜ AYDINLATIYORSUNUZ. GELİYORUZ.",
["zep_ca1_04_01"] = "VEGAS SKY EXPRESS'TEN KAPTAN FORD KONUŞUYOR. İŞARETİNİZİ BEKLİYORUM.",
["zep_ca1_04_02"] = "VEGAS SKY EXPRESS'İN PİLOTU KAPTAN FORD KONUŞUYOR. HAZIRIZ, İŞARETİNİZİ BEKLİYORUZ.",
["zep_ca1_04_03"] = "VEGAS SKY EXPRESS ZEPLİNİ KONUŞUYOR. KOMUTADA KOD ADI \"HEARTBREAKER\". PARTİNİZ İÇİN PAKETİMİZ VAR.",
